    /** Refuses a reference another claim on the sheet (any but the one excluded, null for none) already has, ignoring case. */
    public void checkRef(String sheet, Long excluded, Claims claims) throws InvalidClaimException {
        if (ref != null && claims.refUsed(sheet, ref, excluded)) {
            throw new InvalidClaimException("The reference " + ref + " is already used on the sheet");
        }
    }

    /** The audit fields of this claim for the named person: amount as the screen shows it, ISO date. */
    public String auditFields(String person) {
        return "person=" + person + " amount=" + amount.setScale(2, RoundingMode.UNNECESSARY).toPlainString()
                + " date=" + date;
    }

    /**
     * Refuses a correction unless the claim it names is a SETTLED claim of the same person, and one larger than what
     * remains of that claim: its amount less the corrections already made against it (VOID and DELETED ones, and the
     * one excluded — the claim being edited, null for none — left out).
     */
    public void checkCorrects(String sheet, long person, Long excluded, Claims claims) throws InvalidClaimException {
        if (corrects == null) {
            return;
        }
        Claim corrected = claims.findByNumber(sheet, corrects);
        if (corrected == null || corrected.person() != person || corrected.status() != ClaimStatus.SETTLED) {
            throw new InvalidClaimException("A correction must name a SETTLED claim of the same person");
        }
        BigDecimal remains = new BigDecimal(corrected.amount()).subtract(claims.corrected(sheet, corrects, excluded));
        if (amount.negate().compareTo(remains) > 0) {
            throw new InvalidClaimException("A correction may not exceed what remains of the claim it corrects ("
                    + remains.setScale(2, RoundingMode.HALF_UP).toPlainString() + ")");
        }
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.regex.Pattern;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateClaim {
    private static final Pattern AMOUNT = Pattern.compile("-?\\d+(\\.\\d{1,2})?");
    private static final Pattern NUMBER = Pattern.compile("\\d{1,9}|\\S{1,200}-\\d{1,9}");

    public void validate(@PathVariable("sheet") String sheet, @RequestBody ClaimRequest request, Settings settings,
            Out<ClaimInput> body) throws InvalidClaimException {
        String amount = request == null || request.amount() == null ? "" : request.amount().trim();
        String date = request == null || request.date() == null ? "" : request.date().trim();
        String note = request == null || request.note() == null ? "" : request.note().trim();
        String corrects = request == null || request.corrects() == null ? "" : request.corrects().trim();
        String ref = request == null || request.ref() == null ? "" : request.ref().trim();
        if (!AMOUNT.matcher(amount).matches()) {
            throw new InvalidClaimException("The amount must be a number with up to two decimals");
        }
        // A negative amount is a correction: it must name, by the number it shows (on the sheet, or
        // within its period: <period>-<n>), the claim it corrects; no other claim may.
        BigDecimal value = new BigDecimal(amount);
        if (value.signum() < 0 && !NUMBER.matcher(corrects).matches()) {
            throw new InvalidClaimException("A negative amount must name the number of the claim it corrects");
        }
        if (value.signum() >= 0 && !corrects.isEmpty()) {
            throw new InvalidClaimException("Only a correction (a negative amount) corrects a claim");
        }
        LocalDate on;
        try {
            on = date.isEmpty() ? settings.entryDay(sheet) : LocalDate.parse(date);
        } catch (DateTimeParseException e) {
            throw new InvalidClaimException("Not a valid date: " + date);
        }
        body.set(new ClaimInput(value, on, note, value.signum() < 0 ? numbered(corrects) : null,
                ref.isEmpty() ? null : ref, ClaimInput.tagsOf(request == null ? null : request.tags())));
    }

    /** The number as a claim shows it: a number on the sheet without leading zeros, a period number as given. */
    private static String numbered(String corrects) {
        return corrects.chars().allMatch(Character::isDigit) ? Integer.toString(Integer.parseInt(corrects)) : corrects;
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.holiday.Holidays;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.period.Periods;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.sheet.SheetClock;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

public class BuildClaim {
    public void build(@PathVariable("sheet") String sheet, @RequestParam("user") String user, @Val Person person,
            @Val ClaimInput input, Claims claims, Periods periods, Settings settings, Holidays holidays, SheetClock clock, ClaimLog log, Audit audit, Rollup rollup)
            throws InvalidClaimException {
        // The due-by is fixed now, from the terms in force on the sheet's today (the day the claim is made); the
        // claim belongs to the period its due-by falls in.
        LocalDate today = clock.today(sheet);
        LocalDate dueBy = person.dueBy(sheet, input.date(), today, settings, holidays);
        if (periods.closedOn(sheet, dueBy)) {
            throw new InvalidClaimException("A claim may not be due inside a closed period");
        }
        if (person.retiredBefore(input.date())) {
            throw new InvalidClaimException("A claim may not be dated after the person's retirement date");
        }
        input.checkCorrects(sheet, person.id(), null, claims);
        input.checkRef(sheet, null, claims);
        Rollup.Snapshot before = rollup.take(sheet);
        long id = claims.add(sheet, person.id(), input, dueBy, person.termsOn(sheet, today, settings));
        log.record(sheet, user, id);
        audit.record("CLAIM_ADDED sheet=" + sheet + " by=" + user + " " + input.addedAuditFields(person.name()));
        if (periods.softClosedOn(sheet, dueBy)) {
            claims.setLateEntry(sheet, id);
            audit.record("LATE_ENTRY sheet=" + sheet + " by=" + user + " " + input.auditFields(person.name()));
        }
        rollup.record(sheet, user, before);
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import java.math.BigDecimal;
import java.time.LocalDate;
import net.officefloor.hq.app.period.Periods;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

public class SaveClaim {
    public void save(@PathVariable("sheet") String sheet, @RequestParam("user") String user, @Val Claim claim,
            @Val ClaimInput input, Claims claims, People people, Periods periods, Audit audit, Rollup rollup)
            throws InvalidClaimException {
        // A claim due inside a closed period may not be edited; an edit leaves its due-by, so its period, as it is.
        if (periods.closedOn(sheet, LocalDate.parse(claim.dueBy()))) {
            throw new InvalidClaimException("A claim due inside a closed period may not be edited");
        }
        // Only a draft may be edited: an open claim is voided and a new one added instead.
        if (claim.status() != ClaimStatus.DRAFT) {
            throw new InvalidClaimException("A " + claim.status() + " claim cannot be edited; only a DRAFT can");
        }
        // A claim with lines has the lines' total for its amount: an edit may not type another.
        if (!claim.lines().isEmpty() && input.amount().compareTo(new BigDecimal(claim.amount())) != 0) {
            throw new InvalidClaimException("A claim with lines has their total for its amount");
        }
        Person owner = people.find(sheet, claim.person());
        if (owner.retiredBefore(input.date())) {
            throw new InvalidClaimException("A claim may not be dated after the person's retirement date");
        }
        input.checkCorrects(sheet, owner.id(), claim.id(), claims);
        input.checkRef(sheet, claim.id(), claims);
        Rollup.Snapshot before = rollup.take(sheet);
        if (claim.lockedBy() != null && !claim.lockedBy().equals(user)) {
            throw new InvalidClaimException("The claim is being edited by " + claim.lockedBy());
        }
        // Conditional on the claim still being a draft and not locked by another user's editor, so one another user
        // opened or locked meanwhile is refused; the save releases the lock.
        if (!claims.update(sheet, claim.id(), input, claim.tagsEver(), user)) {
            throw new InvalidClaimException("The claim is no longer a DRAFT, or another user is editing it");
        }
        audit.record("CLAIM_EDITED sheet=" + sheet + " by=" + user + " " + input.auditFields(owner.name()));
        rollup.record(sheet, user, before);
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.time.temporal.ChronoUnit;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.setting.Dated;
import net.officefloor.hq.app.setting.DatedValue;
import net.officefloor.hq.app.setting.Settings;

/**
 * What makes an overdue claim's late charge: the sheet's late percent (two decimals) by date, the one in force on each 30-day boundary after the claim's due-by, and its today; a claim is due
 * by the due-by fixed when it was added. The charge follows the sheet's today, except on a claim bound by a statement, whose due (charge included) is
 * the one the statement bound.
 * It also carries the sheet's policy date, which decides how a claim's live figures round, and each grade's grace
 * as recorded by from-date: the days a claim of a person whose grade in force on its date has a grace in force on
 * that date is given past its due-by before it is overdue. And the sheet's rounding mode as recorded by from-date,
 * which, where one is in force on the date a claim rounds on, decides its rounding in place of the policy date.
 */
public record Late(Dated pct, LocalDate today, LocalDate policy, Map<String, List<DatedValue>> grace,
        List<DatedValue> roundingModes) {

    /**
     * How the claim's live figures round: by the rounding mode in force on the date it rounds on (its own, or for a
     * correction the date of the claim it corrects) where there is one; else half up when that date is before the
     * policy date, half to even on or after it.
     */
    public RoundingMode rounding(Claim claim) {
        LocalDate on = LocalDate.parse(claim.roundsOn());
        String mode = roundingModes == null ? "" : Settings.on(roundingModes, on);
        if ("half-up".equals(mode)) {
            return RoundingMode.HALF_UP;
        }
        if ("half-even".equals(mode)) {
            return RoundingMode.HALF_EVEN;
        }
        return on.isBefore(policy) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
    }

    /**
     * The date the claim's overdue days are counted from: its due-by (fixed when it was added) plus the grace of the
     * grade (its person's in force on its date; null for none) in force on its date, if any.
     */
    public LocalDate graceBy(Claim claim, String grade) {
        LocalDate dueBy = LocalDate.parse(claim.dueBy());
        List<DatedValue> history = grade == null ? null : grace.get(grade);
        String days = history == null ? "" : Settings.on(history, LocalDate.parse(claim.date()));
        return days.isEmpty() ? dueBy : dueBy.plusDays(Integer.parseInt(days));
    }

    /** Whether the claim is overdue: OPEN or PENDING, not deferred, with its {@link #graceBy} before the sheet's today. */
    public boolean overdue(Claim claim, String grade) {
        return !claim.deferred() && (claim.status() == ClaimStatus.OPEN || claim.status() == ClaimStatus.PENDING) && graceBy(claim, grade).isBefore(today);
    }

    /**
     * The claim's late charge on its figure, compounding: for each full 30 days it is overdue, the late percent in force
     * on that boundary (its {@link #graceBy} plus 30, 60, 90 ... days) of the figure plus the charges of the boundaries
     * before it, rounded in hundredths by the claim's {@link #rounding}, the charges added up (a boundary at 0.00 adds
     * nothing); 0.00 when it is not overdue, and always for a correction or a claim whose charge was waived.
     */
    public BigDecimal charge(Claim claim, String grade, BigDecimal figure) {
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        if (figure == null || claim.correction() || claim.waived() || !overdue(claim, grade)) {
            return total;
        }
        LocalDate dueBy = graceBy(claim, grade);
        long periods = ChronoUnit.DAYS.between(dueBy, today) / 30;
        for (long k = 1; k <= periods; k++) {
            BigDecimal boundaryPct = pct.on(dueBy.plusDays(30 * k));
            if (boundaryPct.signum() != 0) {
                total = total.add(figure.add(total).multiply(boundaryPct).movePointLeft(2).setScale(2, rounding(claim)));
            }
        }
        return total;
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;
import net.officefloor.hq.app.asof.AsOfState;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.rate.Rates;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.sheet.SheetClock;
import org.springframework.stereotype.Service;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.TransactionDefinition;
import org.springframework.transaction.support.TransactionTemplate;

/** A claim's due as it stood at the end of a date, as the as-of view works it out (the sheet put as it stood then,
 *  inside a savepoint always rolled back, so nothing is written). */
@Service
public class ClaimDueAsOf {

    /** The claim's due then (null for n/a); existed is false when the claim was not on the sheet then. */
    public record Then(boolean existed, BigDecimal due) {
    }

    private final AsOfState state;
    private final Claims claims;
    private final People people;
    private final Rates rates;
    private final Settings settings;
    private final SheetClock clock;
    private final TransactionTemplate transaction;

    public ClaimDueAsOf(AsOfState state, Claims claims, People people, Rates rates, Settings settings,
            SheetClock clock, PlatformTransactionManager transactions) {
        this.state = state;
        this.claims = claims;
        this.people = people;
        this.rates = rates;
        this.settings = settings;
        this.clock = clock;
        this.transaction = new TransactionTemplate(transactions);
        this.transaction.setPropagationBehavior(TransactionDefinition.PROPAGATION_NESTED);
    }

    public Then on(String sheet, long id, LocalDate date) {
        return transaction.execute((status) -> {
            status.setRollbackOnly();
            state.show(sheet, date);
            Claim claim = claims.find(sheet, id);
            Person person = claim == null ? null : people.find(sheet, claim.person());
            if (person == null) {
                return new Then(false, null);
            }
            return new Then(true, claim.due(rates.list(sheet), person.gradeOn(claim.date()), settings.floor(sheet),
                    settings.late(sheet, clock.today(sheet))));
        });
    }
}
