package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimStatus;
import net.officefloor.hq.app.holiday.Holidays;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.setting.Dated;
import net.officefloor.hq.app.setting.Settings;

/**
 * A person on a sheet: name (unique on the sheet, ignoring case) and grades (A, B or C), each in force from its
 * from-date; grade is the one in force on the sheet's today. The version is raised by one on every save. The
 * retired-from date (yyyy-mm-dd) is null unless they are retired; once it is set they count as retired, whatever
 * the date. Their holds are listed in the order they were added; a hold takes only their cut in the pools, their
 * claims still count in every total. Their own terms are dated (termsFrom, the ones from the beginning of time
 * first); terms are the ones in force on the sheet's today (days), null when they have none then. retiredNow is whether
 * the sheet's today is on or after their retired-from date: from then their OPEN and PENDING claims, unless bound by a
 * statement, count in no live total. Their contact (trimmed, lower-cased, not another's on the sheet) is null when they
 * have none. clashing is whether their name or one of their aliases is already a name or alias on another sheet of
 * the sheet's tree (its ancestors and descendants): every edit of them is refused until it renames them out of it.
 * Their origin is the sheet they were transferred from, null for anyone not transferred. Their retirements are the
 * past ones (each ended by unretiring them), in the order they were unretired. Their tags are lower-cased, repeats
 * dropped, sorted: a claim of theirs counts in the due-total of each. Their flag (a reason and an until-date, both null
 * when never flagged) is in force (flagged) while the sheet's today is on or before its until-date: then only a steward
 * may open a claim of theirs. Their approver (a user name, null when none) may approve or reject their PENDING claims
 * as a steward may.
 */
public record Person(long id, String name, String grade, long version, String retiredFrom, List<Hold> holds,
        List<GradeFrom> grades, Integer terms, boolean retiredNow, String contact, boolean clashing, String origin,
        List<Retirement> retirements, List<String> tags, List<TermsFrom> termsFrom, String flagReason, String flagUntil,
        boolean flagged, String approver) {

    /**
     * Whether the claim, theirs, counts toward the live totals: it counts, unless it is open, not bound by a statement,
     * and their retirement date is reached. A hold (theirs or the claim's) does not take it out; it only takes their
     * cut in the pools.
     */
    public boolean counts(Claim claim) {
        if (!claim.counts()) {
            return false;
        }
        if (claim.status() == ClaimStatus.SETTLED || claim.bound()) {
            return true;
        }
        return !retiredNow;
    }

    /**
     * Whether the claim, theirs, counts toward claimed and the claimed-total: as {@link #counts}.
     */
    public boolean countsClaimed(Claim claim) {
        if (!claim.counts()) {
            return false;
        }
        if (claim.status() == ClaimStatus.SETTLED || claim.bound()) {
            return true;
        }
        return !retiredNow;
    }

    /** This person as they stand with the date for the sheet's today: their grade in force then, and retired then or not. */
    public Person on(LocalDate today) {
        return new Person(id, name, gradeOn(grades, today), version, retiredFrom, holds, grades,
                termsOn(termsFrom, today), retiredOn(retiredFrom, today), contact, clashing, origin, retirements, tags,
                termsFrom, flagReason, flagUntil, flaggedOn(flagUntil, today), approver);
    }

    /** Whether the sheet's today is on or before the flag's until-date (null: never flagged). */
    static boolean flaggedOn(String flagUntil, LocalDate today) {
        return flagUntil != null && !today.isAfter(LocalDate.parse(flagUntil));
    }

    /** Whether the sheet's today is on or after the retired-from date (null: never retired). */
    static boolean retiredOn(String retiredFrom, LocalDate today) {
        return retiredFrom != null && !today.isBefore(LocalDate.parse(retiredFrom));
    }

    /**
     * Whether the claim, theirs, counts toward a period ending on the date: by the status it had at the end of that
     * day (OPEN, PENDING or SETTLED; not yet added: no), unless deferred now, or open now, not bound by a statement
     * and their retirement date is reached (a hold does not take it out).
     */
    public boolean countsOn(Claim claim, LocalDate end) {
        ClaimStatus then = claim.statusOn(end);
        if (claim.deferred() || then == null) {
            return false;
        }
        if (then == ClaimStatus.SETTLED) {
            return true;
        }
        if (then != ClaimStatus.OPEN && then != ClaimStatus.PENDING) {
            return false;
        }
        return (claim.status() != ClaimStatus.OPEN && claim.status() != ClaimStatus.PENDING) || claim.bound()
                || !retiredNow;
    }

    /**
     * Whether a claim dated {@code date} is after this person's retirement, or after the from and before the to of a
     * past one, and so refused.
     */
    public boolean retiredBefore(LocalDate date) {
        return (retiredFrom != null && date.isAfter(LocalDate.parse(retiredFrom)))
                || retirements.stream().anyMatch((r) -> r.within(date.toString()));
    }

    /** The grade in force on the date: the one whose from-date is the latest on or before it (null when none). */
    public String gradeOn(LocalDate date) {
        return gradeOn(grades, date);
    }

    /**
     * Whether the claim has a figure apart from the grade in force on {@code today}: one it keeps (settled or
     * bound), one at another grade, in force on its date, or one from a rate that ended (its to-date) on or before
     * today, the claim not being dated after today. Their due-total is n/a only when no claim does and that grade
     * has no rate on today.
     */
    public boolean figureApartFrom(Claim claim, LocalDate today, List<Rate> rates, Dated floor) {
        String then = gradeOn(claim.date());
        return claim.fixed()
                || (then != null && !then.equals(gradeOn(today)) && claim.figure(rates, then, floor) != null)
                || (then != null && !LocalDate.parse(claim.date()).isAfter(today)
                        && claim.figure(rates, then, floor) != null);
    }

    /**
     * The due-by of a claim of theirs dated {@code date}, fixed when it is made on {@code made} (the sheet's today
     * then): the terms-th business day after the date (skipping weekends and the sheet's holidays as they stand now),
     * the terms being those in force on the day it is made (see {@link #termsOn}).
     */
    public LocalDate dueBy(String sheet, LocalDate date, LocalDate made, Settings settings, Holidays holidays) {
        return holidays.businessDaysAfter(sheet, date, termsOn(sheet, made, settings));
    }

    /**
     * The terms a claim of theirs made on {@code made} (the sheet's today then) is fixed with: their own in force that
     * day, else those of the grade they had that day, else the sheet's that day.
     */
    public int termsOn(String sheet, LocalDate made, Settings settings) {
        Integer own = termsOn(termsFrom, made);
        return own != null ? own : settings.terms(sheet, gradeOn(made), made);
    }

    /** Their own terms in force on the date: the ones whose from-date is the latest on or before it (null: none). */
    static Integer termsOn(List<TermsFrom> termsFrom, LocalDate date) {
        TermsFrom found = null;
        for (TermsFrom t : termsFrom) {
            if (t.from() != null && LocalDate.parse(t.from()).isAfter(date)) {
                continue;
            }
            if (found == null || (t.from() != null && (found.from() == null || t.from().compareTo(found.from()) > 0))) {
                found = t;
            }
        }
        return found == null ? null : found.terms();
    }

    /** The grade in force on the claim's date (yyyy-mm-dd). */
    public String gradeOn(String date) {
        return gradeOn(LocalDate.parse(date));
    }

    static String gradeOn(List<GradeFrom> grades, LocalDate date) {
        GradeFrom found = null;
        for (GradeFrom g : grades) {
            if (g.from() != null && LocalDate.parse(g.from()).isAfter(date)) {
                continue;
            }
            if (found == null || (found.from() != null && g.from() != null && g.from().compareTo(found.from()) > 0)
                    || (found.from() == null && g.from() != null)) {
                found = g;
            }
        }
        return found == null ? null : found.grade();
    }
}
package net.officefloor.hq.app.person;

import java.sql.Date;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.HashSet;
import java.util.Locale;
import java.util.Set;
import net.officefloor.hq.app.alias.Aliases;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.sheet.SheetClock;
import org.springframework.dao.DuplicateKeyException;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.stereotype.Repository;

/** The people kept per sheet, each with their grades by from-date. */
@Repository
public class People {

    private static final String COLUMNS = "SELECT id, name, version, retired_from, terms, contact, origin, tags, flag_reason, flag_until, approver FROM person";

    private record Row(long id, String name, long version, String retiredFrom, Integer terms, String contact, String origin, String tags,
            String flagReason, String flagUntil, String approver) {
    }

    private final JdbcTemplate jdbc;
    private final SheetClock clock;
    private final Aliases aliases;
    private final Settings settings;

    public People(JdbcTemplate jdbc, SheetClock clock, Aliases aliases, Settings settings) {
        this.jdbc = jdbc;
        this.clock = clock;
        this.aliases = aliases;
        this.settings = settings;
    }

    /** Whether the grade is retired on the sheet: it can no longer be chosen for a person. */
    public boolean gradeRetired(String sheet, String grade) {
        Integer found = jdbc.queryForObject("SELECT COUNT(*) FROM grade_retired WHERE sheet = ? AND grade = ?",
                Integer.class, sheet, grade);
        return found != null && found > 0;
    }

    /** Every name and alias, lower-cased, on the other sheets of the sheet's tree (its ancestors and descendants). */
    private Set<String> treeNames(String sheet) {
        Set<String> names = new HashSet<>();
        for (String other : settings.tree(sheet)) {
            names.addAll(jdbc.queryForList("SELECT name_key FROM person WHERE sheet = ?", String.class, other));
            names.addAll(jdbc.queryForList("SELECT alias_key FROM person_alias WHERE sheet = ?", String.class, other));
        }
        return names;
    }

    /** Whether the name is already a name or alias on another sheet of the sheet's tree, ignoring case. */
    public boolean usedInTree(String sheet, String name) {
        return treeNames(sheet).contains(name.toLowerCase(Locale.ROOT));
    }

    /** Whether an alias of the person is already a name or alias on another sheet of the sheet's tree. */
    public boolean aliasClashes(String sheet, long id) {
        Set<String> names = treeNames(sheet);
        return jdbc.queryForList("SELECT alias_key FROM person_alias WHERE sheet = ? AND person_id = ?", String.class,
                sheet, id).stream().anyMatch(names::contains);
    }

    private List<Person> query(String sheet, String where, Object... args) {
        List<Row> rows = jdbc.query(COLUMNS + " " + where, (rs, i) -> new Row(rs.getLong("id"), rs.getString("name"),
                rs.getLong("version"),
                rs.getDate("retired_from") == null ? null : rs.getDate("retired_from").toLocalDate().toString(),
                rs.getObject("terms", Integer.class), rs.getString("contact"), rs.getString("origin"), rs.getString("tags"),
                rs.getString("flag_reason"),
                rs.getDate("flag_until") == null ? null : rs.getDate("flag_until").toLocalDate().toString(),
                rs.getString("approver")), args);
        if (rows.isEmpty()) {
            return List.of();
        }
        Map<Long, List<GradeFrom>> grades = new HashMap<>();
        jdbc.query("SELECT g.person_id, g.grade, g.from_date FROM person_grade g JOIN person p ON p.id = g.person_id"
                + " WHERE p.sheet = ? ORDER BY g.person_id, g.from_key", (rs) -> {
                    grades.computeIfAbsent(rs.getLong("person_id"), (k) -> new ArrayList<>())
                            .add(new GradeFrom(rs.getString("grade"),
                                    rs.getDate("from_date") == null ? null : rs.getDate("from_date").toLocalDate().toString()));
                }, sheet);
        Map<Long, List<TermsFrom>> dated = new HashMap<>();
        jdbc.query("SELECT t.person_id, t.terms, t.from_date FROM person_terms t JOIN person p ON p.id = t.person_id"
                + " WHERE p.sheet = ? ORDER BY t.person_id, t.from_date", (rs) -> {
                    dated.computeIfAbsent(rs.getLong("person_id"), (k) -> new ArrayList<>())
                            .add(new TermsFrom(rs.getObject("terms", Integer.class),
                                    rs.getDate("from_date").toLocalDate().toString()));
                }, sheet);
        Map<Long, List<Hold>> holds = new HashMap<>();
        jdbc.query("SELECT h.person_id, h.from_date, h.to_date FROM person_hold h JOIN person p ON p.id = h.person_id"
                + " WHERE p.sheet = ? ORDER BY h.person_id, h.id", (rs) -> {
                    holds.computeIfAbsent(rs.getLong("person_id"), (k) -> new ArrayList<>())
                            .add(new Hold(rs.getDate("from_date").toLocalDate().toString(),
                                    rs.getDate("to_date") == null ? null : rs.getDate("to_date").toLocalDate().toString()));
                }, sheet);
        Map<Long, List<Retirement>> retirements = new HashMap<>();
        jdbc.query("SELECT r.person_id, r.from_date, r.to_date FROM person_retirement r JOIN person p ON p.id = r.person_id"
                + " WHERE p.sheet = ? ORDER BY r.person_id, r.id", (rs) -> {
                    retirements.computeIfAbsent(rs.getLong("person_id"), (k) -> new ArrayList<>())
                            .add(new Retirement(rs.getDate("from_date").toLocalDate().toString(),
                                    rs.getDate("to_date").toLocalDate().toString()));
                }, sheet);
        Set<String> tree = treeNames(sheet);
        Map<Long, List<String>> aliasKeys = new HashMap<>();
        jdbc.query("SELECT person_id, alias_key FROM person_alias WHERE sheet = ?", (rs) -> {
            aliasKeys.computeIfAbsent(rs.getLong("person_id"), (k) -> new ArrayList<>()).add(rs.getString("alias_key"));
        }, sheet);
        LocalDate today = clock.today(sheet);
        List<Person> people = new ArrayList<>();
        for (Row r : rows) {
            List<GradeFrom> mine = List.copyOf(grades.getOrDefault(r.id(), List.of()));
            List<TermsFrom> terms = new ArrayList<>();
            terms.add(new TermsFrom(r.terms(), null));
            terms.addAll(dated.getOrDefault(r.id(), List.of()));
            people.add(new Person(r.id(), r.name(), Person.gradeOn(mine, today), r.version(), r.retiredFrom(),
                    List.copyOf(holds.getOrDefault(r.id(), List.of())), mine, Person.termsOn(terms, today),
                    Person.retiredOn(r.retiredFrom(), today), r.contact(),
                    tree.contains(r.name().toLowerCase(Locale.ROOT))
                            || aliasKeys.getOrDefault(r.id(), List.of()).stream().anyMatch(tree::contains), r.origin(),
                    List.copyOf(retirements.getOrDefault(r.id(), List.of())),
                    r.tags().isEmpty() ? List.of() : List.of(r.tags().split(",")), List.copyOf(terms),
                    r.flagReason(), r.flagUntil(), Person.flaggedOn(r.flagUntil(), today), r.approver()));
        }
        return people;
    }

    /** Everyone on the sheet, in list order (by position; new people go to the end). */
    public List<Person> list(String sheet) {
        return query(sheet, "WHERE sheet = ? ORDER BY list_position, id", sheet);
    }

    /** The position after the sheet's last, where a new person goes. */
    public static final String NEXT_POSITION = "(SELECT COALESCE(MAX(n.list_position), 0) + 1 FROM person n WHERE n.sheet = ?)";

    /** Swaps the list positions of two people on the sheet. */
    public void swapPositions(String sheet, long a, long b) {
        Long pa = jdbc.queryForObject("SELECT list_position FROM person WHERE sheet = ? AND id = ?", Long.class, sheet, a);
        Long pb = jdbc.queryForObject("SELECT list_position FROM person WHERE sheet = ? AND id = ?", Long.class, sheet, b);
        jdbc.update("UPDATE person SET list_position = ? WHERE sheet = ? AND id = ?", pb, sheet, a);
        jdbc.update("UPDATE person SET list_position = ? WHERE sheet = ? AND id = ?", pa, sheet, b);
    }

    public Person find(String sheet, long id) {
        List<Person> found = query(sheet, "WHERE sheet = ? AND id = ?", sheet, id);
        return found.isEmpty() ? null : found.get(0);
    }

    /** The person on the sheet with this name or alias, ignoring case; null when there is none. */
    public Person findByName(String sheet, String name) {
        List<Person> found = query(sheet, "WHERE sheet = ? AND name_key = LOWER(?)", sheet, name);
        if (found.isEmpty()) {
            found = query(sheet, "WHERE sheet = ? AND id IN (SELECT person_id FROM person_alias WHERE sheet = ?"
                    + " AND alias_key = LOWER(?))", sheet, sheet, name);
        }
        return found.isEmpty() ? null : found.get(0);
    }

    /** Whether someone on the sheet other than {@code except} has this name, ignoring case. */
    public boolean nameTaken(String sheet, String name, Long except) {
        Integer taken = jdbc.queryForObject(
                "SELECT COUNT(*) FROM person WHERE sheet = ? AND name_key = LOWER(?) AND (? IS NULL OR id <> ?)",
                Integer.class, sheet, name, except, except);
        return taken != null && taken > 0;
    }

    /** Adds the person with their first grade, which applies from the beginning of time. */
    public Person add(String sheet, String name, String grade) throws DuplicatePersonNameException {
        return add(sheet, name, grade, null, null);
    }

    /** Adds the person with their first grade, which applies from the beginning of time, their own terms and contact (null: none). */
    public Person add(String sheet, String name, String grade, Integer terms, String contact)
            throws DuplicatePersonNameException {
        if (nameTaken(sheet, name, null) || aliases.taken(sheet, name) || usedInTree(sheet, name)) {
            throw new DuplicatePersonNameException(name);
        }
        GeneratedKeyHolder keys = new GeneratedKeyHolder();
        try {
            insert(sheet, name, keys);
        } catch (DuplicateKeyException e) {
            throw new DuplicatePersonNameException(name);
        }
        long id = keys.getKey().longValue();
        setGrade(id, grade, null);
        setTerms(id, terms);
        setContact(id, contact);
        return find(sheet, id);
    }

    private void insert(String sheet, String name, GeneratedKeyHolder keys) {
        jdbc.update(con -> {
            var ps = con.prepareStatement("INSERT INTO person (sheet, name, list_position) VALUES (?, ?, "
                    + NEXT_POSITION + ")", new String[] { "id" });
            ps.setString(1, sheet);
            ps.setString(2, name);
            ps.setString(3, sheet);
            return ps;
        }, keys);
    }

    /** Records the person's grade from the from-date (null: from the beginning of time), replacing the one there for it. */
    public void setGrade(long id, String grade, LocalDate from) {
        Date date = from == null ? null : Date.valueOf(from);
        if (jdbc.update("UPDATE person_grade SET grade = ? WHERE person_id = ? AND from_date IS NOT DISTINCT FROM ?",
                grade, id, date) == 0) {
            jdbc.update("INSERT INTO person_grade (person_id, grade, from_date) VALUES (?, ?, ?)", id, grade, date);
        }
    }

    /** Turns every grade record of the person on the grade into the other grade, whatever its from-date. */
    public void regrade(long id, String grade, String into) {
        jdbc.update("UPDATE person_grade SET grade = ? WHERE person_id = ? AND grade = ?", into, id, grade);
    }

    /** Sets the person's own terms from the beginning of time (null: none). */
    public void setTerms(long id, Integer terms) {
        jdbc.update("UPDATE person SET terms = ? WHERE id = ?", terms, id);
    }

    /** Records the person's own terms (null: none) from the from-date, replacing the ones there for it. */
    public void setTerms(long id, Integer terms, LocalDate from) {
        if (jdbc.update("UPDATE person_terms SET terms = ? WHERE person_id = ? AND from_date = ?", terms, id,
                Date.valueOf(from)) == 0) {
            jdbc.update("INSERT INTO person_terms (person_id, terms, from_date) VALUES (?, ?, ?)", id, terms,
                    Date.valueOf(from));
        }
    }

    /** Sets the person's contact (null: none). */
    public void setContact(long id, String contact) {
        jdbc.update("UPDATE person SET contact = ? WHERE id = ?", contact, id);
    }

    /** Sets the person's tags (lower-cased, sorted; empty: none). */
    public void setTags(long id, List<String> tags) {
        jdbc.update("UPDATE person SET tags = ? WHERE id = ?", String.join(",", tags), id);
    }

    /** Whether someone on the sheet other than {@code except} has this contact. */
    public boolean contactTaken(String sheet, String contact, Long except) {
        Integer taken = jdbc.queryForObject(
                "SELECT COUNT(*) FROM person WHERE sheet = ? AND contact = ? AND (? IS NULL OR id <> ?)",
                Integer.class, sheet, contact, except, except);
        return taken != null && taken > 0;
    }

    /** Retire the person from the date. */
    public void retire(String sheet, long id, LocalDate from) {
        jdbc.update("UPDATE person SET retired_from = ? WHERE sheet = ? AND id = ?", Date.valueOf(from), sheet, id);
    }

    /** Unretire the person on the date, keeping the retirement from its from-date to that date as a past one. */
    public void unretire(String sheet, long id, LocalDate from, LocalDate on) {
        jdbc.update("INSERT INTO person_retirement (person_id, from_date, to_date) VALUES (?, ?, ?)", id,
                Date.valueOf(from), Date.valueOf(on));
        jdbc.update("UPDATE person SET retired_from = NULL WHERE sheet = ? AND id = ?", sheet, id);
    }

    /** Adds a hold to the person. */
    public void hold(long id, Hold hold) {
        jdbc.update("INSERT INTO person_hold (person_id, from_date, to_date) VALUES (?, ?, ?)", id,
                Date.valueOf(hold.from()), hold.to() == null ? null : Date.valueOf(hold.to()));
    }

    /** Flags the person with the reason until the date, replacing any flag they had. */
    public void flag(long id, String reason, LocalDate until) {
        jdbc.update("UPDATE person SET flag_reason = ?, flag_until = ? WHERE id = ?", reason, Date.valueOf(until), id);
    }

    /** Sets the person's approver (null: none), replacing any they had. */
    public void setApprover(long id, String approver) {
        jdbc.update("UPDATE person SET approver = ? WHERE id = ?", approver, id);
    }

    /** Save the person's name over the version it carries, raising the version; refused when it has moved on. */
    public void update(String sheet, Person person) throws DuplicatePersonNameException, StalePersonException {
        if (nameTaken(sheet, person.name(), person.id()) || aliases.taken(sheet, person.name())) {
            throw new DuplicatePersonNameException(person.name());
        }
        int updated;
        try {
            updated = jdbc.update(
                    "UPDATE person SET name = ?, version = version + 1 WHERE sheet = ? AND id = ? AND version = ?",
                    person.name(), sheet, person.id(), person.version());
        } catch (DuplicateKeyException e) {
            throw new DuplicatePersonNameException(person.name());
        }
        if (updated == 0) {
            throw new StalePersonException(person.id());
        }
    }
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import net.officefloor.hq.app.sheet.SheetClock;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

/** The hold to add: from the date given (the sheet's today when blank) to the to-date given (none when blank), which may not be before it. */
public class ValidateHold {
    public void validate(@PathVariable("sheet") String sheet, @RequestBody HoldRequest request, SheetClock clock,
            Out<Hold> hold) throws InvalidPersonException {
        hold.set(of(sheet, request, clock));
    }

    /** The hold the request asks for, refused on a bad date or a to-date before the from-date; the bulk hold uses it too. */
    static Hold of(String sheet, HoldRequest request, SheetClock clock) throws InvalidPersonException {
        String from = request == null || request.from() == null ? "" : request.from().trim();
        String to = request == null || request.to() == null ? "" : request.to().trim();
        LocalDate start = from.isEmpty() ? clock.today(sheet) : parse(from);
        LocalDate end = to.isEmpty() ? null : parse(to);
        if (end != null && end.isBefore(start)) {
            throw new InvalidPersonException("A hold may not end before it starts");
        }
        return new Hold(start.toString(), end == null ? null : end.toString());
    }

    private static LocalDate parse(String date) throws InvalidPersonException {
        try {
            return LocalDate.parse(date);
        } catch (DateTimeParseException e) {
            throw new InvalidPersonException("Not a valid date: " + date);
        }
    }
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import net.officefloor.hq.app.role.Role;
import net.officefloor.hq.app.role.Roles;
import net.officefloor.hq.app.sheet.SheetClock;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestParam;

/** Only a steward flags a person, with a reason (not blank) until the date given (the sheet's today when blank). */
public class ValidateFlag {
    public void validate(@PathVariable("sheet") String sheet, @RequestParam("user") String user,
            @RequestBody FlagRequest request, Roles roles, SheetClock clock, Out<Flag> flag)
            throws InvalidPersonException {
        if (!Role.STEWARD.equals(roles.of(sheet, user))) {
            throw new InvalidPersonException("Only a steward may flag a person");
        }
        String reason = request == null || request.reason() == null ? "" : request.reason().trim();
        String until = request == null || request.until() == null ? "" : request.until().trim();
        if (reason.isEmpty()) {
            throw new InvalidPersonException("A flag needs a reason");
        }
        LocalDate date;
        try {
            date = until.isEmpty() ? clock.today(sheet) : LocalDate.parse(until);
        } catch (DateTimeParseException e) {
            throw new InvalidPersonException("Not a valid date: " + until);
        }
        flag.set(new Flag(reason, date));
    }
}

package net.officefloor.hq.app.period;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimStatus;
import net.officefloor.hq.app.claim.Claims;
import net.officefloor.hq.app.claim.Late;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.pool.Pools;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.Rates;
import net.officefloor.hq.app.setting.Dated;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.sheet.SheetClock;
import org.springframework.stereotype.Service;

/**
 * Closes a period, fixing its due-total now, and each person's on the sheet (the part of it from their claims): the due now of the claims whose due-by falls in it
 * that counted at the end of its last day (OPEN, PENDING and SETTLED then by their status log, but not a deferred one, nor an unbound open one dated
 * within its person's hold) (a claim with no rate adds nothing); and each person's carried figure for it: the due now of
 * their claims that count at its end whose due-by falls in an earlier period (one ending before it starts) and that were
 * still OPEN or PENDING at its end by their status log, plus their opening balance for it; and every pool member's cut as it stands now. Shared by a close by hand and the auto close of a today change.
 */
@Service
public class PeriodCloser {

    private final Periods periods;
    private final Claims claims;
    private final People people;
    private final Rates rates;
    private final Settings settings;
    private final SheetClock clock;
    private final Audit audit;
    private final Pools pools;

    public PeriodCloser(Periods periods, Claims claims, People people, Rates rates, Settings settings, SheetClock clock,
            Audit audit, Pools pools) {
        this.pools = pools;
        this.periods = periods;
        this.claims = claims;
        this.people = people;
        this.rates = rates;
        this.settings = settings;
        this.clock = clock;
        this.audit = audit;
    }

    /** Closes the period found open on the sheet; false when it was already closed. An auto close is audited auto=yes. */
    public boolean close(String sheet, String user, Period found, boolean auto) {
        return close(sheet, user, found, auto, false);
    }

    /**
     * Closes the period found open (or soft-closed) on the sheet, or soft-closes it, fixing its figures afresh; false
     * when it was already closed, or for a soft close already soft-closed.
     */
    public boolean close(String sheet, String user, Period found, boolean auto, boolean soft) {
        LocalDate from = LocalDate.parse(found.from());
        LocalDate to = LocalDate.parse(found.to());
        Map<Long, Person> byId = people.list(sheet).stream().collect(Collectors.toMap(Person::id, (p) -> p));
        List<Rate> sheetRates = rates.list(sheet);
        Dated floor = settings.floor(sheet);
        Late late = settings.late(sheet, clock.today(sheet));
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        Map<Long, BigDecimal> perPerson = new LinkedHashMap<>();
        byId.keySet().forEach((id) -> perPerson.put(id, BigDecimal.ZERO.setScale(2)));
        Map<Long, BigDecimal> carried = new LinkedHashMap<>(perPerson);
        periods.openings(sheet, found.name()).forEach((id, amount) -> {
            if (carried.containsKey(id)) {
                carried.merge(id, amount, BigDecimal::add);
            }
        });
        List<Period> sheetPeriods = periods.list(sheet);
        List<Claim> sheetClaims = claims.list(sheet);
        for (Claim claim : sheetClaims) {
            Person person = byId.get(claim.person());
            LocalDate dueBy = LocalDate.parse(claim.dueBy());
            boolean earlier = sheetPeriods.stream().anyMatch((p) -> !dueBy.isBefore(LocalDate.parse(p.from()))
                    && !dueBy.isAfter(LocalDate.parse(p.to())) && LocalDate.parse(p.to()).isBefore(from));
            ClaimStatus then = claim.statusOn(to);
            if (person == null || !earlier || (then != ClaimStatus.OPEN && then != ClaimStatus.PENDING)
                    || !person.countsOn(claim, to)) {
                continue;
            }
            BigDecimal due = claim.due(sheetRates, person.gradeOn(claim.date()), floor, late);
            if (due != null) {
                carried.merge(person.id(), due, BigDecimal::add);
            }
        }
        for (Claim claim : sheetClaims) {
            LocalDate date = LocalDate.parse(claim.dueBy());
            Person person = byId.get(claim.person());
            if (person == null || !person.countsOn(claim, to) || date.isBefore(from) || date.isAfter(to)) {
                continue;
            }
            BigDecimal due = claim.due(sheetRates, person.gradeOn(claim.date()), floor, late);
            if (due != null) {
                total = total.add(due);
                perPerson.merge(person.id(), due, BigDecimal::add);
            }
        }
        if (!periods.close(sheet, found.name(), total, perPerson, carried, soft)) {
            return false;
        }
        periods.fixPoolCuts(sheet, found.name(), pools.currentCuts(sheet));
        audit.record((soft ? "PERIOD_SOFT_CLOSED" : "PERIOD_CLOSED") + " sheet=" + sheet + " by=" + user + " period=" + found.name() + " total="
                + total.toPlainString() + (auto ? " auto=yes" : ""));
        return true;
    }

    /**
     * Closes, in order of their to-dates, every open (neither closed nor soft-closed) period of the sheet whose to-date plus the grace days is before
     * the sheet's today; none when the sheet has no grace days.
     */
    public void autoClose(String sheet, String user) {
        Integer grace = settings.graceDays(sheet);
        if (grace == null) {
            return;
        }
        LocalDate today = clock.today(sheet);
        List<Period> due = periods.list(sheet).stream()
                .filter((p) -> !p.fixed() && LocalDate.parse(p.to()).plusDays(grace).isBefore(today))
                .sorted(Comparator.comparing(Period::to)).toList();
        for (Period period : due) {
            close(sheet, user, period, true);
        }
    }
}
package net.officefloor.hq.app.period;

import java.math.BigDecimal;
import java.sql.Date;
import java.time.LocalDate;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Repository;

/** The periods kept per sheet. */
@Repository
public class Periods {

    private static final RowMapper<Period> ROW = (rs, i) -> new Period(rs.getString("name"),
            rs.getDate("from_date").toLocalDate().toString(), rs.getDate("to_date").toLocalDate().toString(),
            rs.getBoolean("closed"),
            rs.getBigDecimal("closed_total") == null ? null : rs.getBigDecimal("closed_total").toPlainString(),
            Map.of(), rs.getBoolean("soft"), (Integer) rs.getObject("claim_cap"), Map.of(), Map.of(),
            rs.getBoolean("locked"), rs.getLong("added_seq"));

    private static final String COLUMNS = "SELECT name, from_date, to_date, closed, closed_total, soft, claim_cap, locked, added_seq FROM period";

    private final JdbcTemplate jdbc;

    public Periods(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** Every period on the sheet, by from-date. */
    public List<Period> list(String sheet) {
        return jdbc.query(COLUMNS + " WHERE sheet = ? ORDER BY from_date", ROW, sheet).stream()
                .map((p) -> withOpenings(sheet, withPeople(sheet, p))).toList();
    }

    /** The period with its people's opening balances. */
    private Period withOpenings(String sheet, Period period) {
        Map<Long, String> openings = new LinkedHashMap<>();
        jdbc.query("SELECT person, amount FROM period_opening WHERE sheet = ? AND period = ? ORDER BY person",
                (rs) -> {
                    openings.put(rs.getLong("person"), rs.getBigDecimal("amount").toPlainString());
                }, sheet, period.name());
        return new Period(period.name(), period.from(), period.to(), period.closed(), period.closedTotal(),
                period.closedPeople(), period.soft(), period.cap(), period.closedCarried(), openings, period.locked(),
                period.added());
    }

    /** Each person's opening balance for the period (by person id); none for a person with no opening. */
    public Map<Long, BigDecimal> openings(String sheet, String name) {
        Map<Long, BigDecimal> openings = new LinkedHashMap<>();
        jdbc.query("SELECT person, amount FROM period_opening WHERE sheet = ? AND period = ?",
                (rs) -> {
                    openings.put(rs.getLong("person"), rs.getBigDecimal("amount"));
                }, sheet, name);
        return openings;
    }

    /** Adds the amount to the person's opening balance for the period. */
    public void addOpening(String sheet, String name, long person, BigDecimal amount) {
        if (jdbc.update("UPDATE period_opening SET amount = amount + ? WHERE sheet = ? AND period = ? AND person = ?",
                amount, sheet, name, person) == 0) {
            jdbc.update("INSERT INTO period_opening (sheet, period, person, amount) VALUES (?, ?, ?, ?)", sheet, name,
                    person, amount);
        }
    }

    /** Takes the amount back off the person's opening balance for the period, dropping it when nothing is left. */
    public void takeOpening(String sheet, String name, long person, BigDecimal amount) {
        jdbc.update("UPDATE period_opening SET amount = amount - ? WHERE sheet = ? AND period = ? AND person = ?",
                amount, sheet, name, person);
        jdbc.update("DELETE FROM period_opening WHERE sheet = ? AND period = ? AND person = ? AND amount = 0", sheet,
                name, person);
    }

    /** Removes the period with its openings, fixed figures and pool cuts. */
    public void remove(String sheet, String name) {
        jdbc.update("DELETE FROM period_opening WHERE sheet = ? AND period = ?", sheet, name);
        jdbc.update("DELETE FROM period_person_total WHERE sheet = ? AND period = ?", sheet, name);
        jdbc.update("DELETE FROM period_pool_cut WHERE sheet = ? AND period = ?", sheet, name);
        jdbc.update("DELETE FROM period WHERE sheet = ? AND name = ?", sheet, name);
    }

    /** The period with its people's due-totals and carried figures fixed when it was closed. */
    private Period withPeople(String sheet, Period period) {
        if (!period.fixed()) {
            return period;
        }
        Map<Long, String> people = new LinkedHashMap<>();
        Map<Long, String> carried = new LinkedHashMap<>();
        jdbc.query("SELECT person, total, carried FROM period_person_total WHERE sheet = ? AND period = ? ORDER BY person",
                (rs) -> {
                    people.put(rs.getLong("person"), rs.getBigDecimal("total").toPlainString());
                    carried.put(rs.getLong("person"), rs.getBigDecimal("carried").toPlainString());
                }, sheet, period.name());
        return new Period(period.name(), period.from(), period.to(), period.closed(), period.closedTotal(), people,
                period.soft(), period.cap(), carried, period.openings(), period.locked(), period.added());
    }

    /** The sheet's period of the name, or null when there is none. */
    public Period find(String sheet, String name) {
        List<Period> found = jdbc.query(COLUMNS + " WHERE sheet = ? AND name = ?", ROW, sheet, name);
        return found.isEmpty() ? null : found.get(0);
    }

    /** Whether the date falls inside a closed period of the sheet. */
    public boolean closedOn(String sheet, LocalDate date) {
        Integer n = jdbc.queryForObject(
                "SELECT COUNT(*) FROM period WHERE sheet = ? AND closed AND from_date <= ? AND to_date >= ?",
                Integer.class, sheet, Date.valueOf(date), Date.valueOf(date));
        return n != null && n > 0;
    }

    /** Whether the date falls inside a soft-closed period of the sheet. */
    public boolean softClosedOn(String sheet, LocalDate date) {
        Integer n = jdbc.queryForObject(
                "SELECT COUNT(*) FROM period WHERE sheet = ? AND soft AND from_date <= ? AND to_date >= ?",
                Integer.class, sheet, Date.valueOf(date), Date.valueOf(date));
        return n != null && n > 0;
    }

    /** The name of the sheet's period the date falls inside, or null when it is in none. */
    public String nameOn(String sheet, LocalDate date) {
        List<String> found = jdbc.queryForList("SELECT name FROM period WHERE sheet = ? AND from_date <= ? AND to_date >= ?",
                String.class, sheet, Date.valueOf(date), Date.valueOf(date));
        return found.isEmpty() ? null : found.get(0);
    }

    /** The sheet's period the date falls inside, or null when it is in none. */
    public Period on(String sheet, LocalDate date) {
        List<Period> found = jdbc.query(COLUMNS + " WHERE sheet = ? AND from_date <= ? AND to_date >= ?", ROW, sheet,
                Date.valueOf(date), Date.valueOf(date));
        return found.isEmpty() ? null : found.get(0);
    }

    /** Whether the sheet has a period of the name. */
    public boolean named(String sheet, String name) {
        Integer n = jdbc.queryForObject("SELECT COUNT(*) FROM period WHERE sheet = ? AND name = ?", Integer.class,
                sheet, name);
        return n != null && n > 0;
    }

    /** Whether any period on the sheet shares a date with the inclusive range. */
    public boolean overlaps(String sheet, PeriodInput input) {
        Integer n = jdbc.queryForObject(
                "SELECT COUNT(*) FROM period WHERE sheet = ? AND from_date <= ? AND to_date >= ?", Integer.class,
                sheet, Date.valueOf(input.to()), Date.valueOf(input.from()));
        return n != null && n > 0;
    }

    public void add(String sheet, PeriodInput input) {
        jdbc.update("INSERT INTO period (sheet, name, from_date, to_date, claim_cap) VALUES (?, ?, ?, ?, ?)", sheet,
                input.name(), Date.valueOf(input.from()), Date.valueOf(input.to()), input.cap());
    }

    /**
     * Closes the period (or soft-closes it) with its due-total and each person's due-total and carried figure (by id)
     * fixed afresh; false when it was
     * already closed, or for a soft close already soft-closed (or is gone). Closing a soft-closed period is allowed.
     */
    public boolean close(String sheet, String name, BigDecimal total, Map<Long, BigDecimal> people,
            Map<Long, BigDecimal> carried, boolean soft) {
        String sql = soft
                ? "UPDATE period SET soft = TRUE, closed_total = ? WHERE sheet = ? AND name = ? AND NOT closed AND NOT soft"
                : "UPDATE period SET closed = TRUE, soft = FALSE, closed_total = ? WHERE sheet = ? AND name = ? AND NOT closed";
        if (jdbc.update(sql, total, sheet, name) != 1) {
            return false;
        }
        jdbc.update("DELETE FROM period_person_total WHERE sheet = ? AND period = ?", sheet, name);
        people.forEach((person, due) -> jdbc.update(
                "INSERT INTO period_person_total (sheet, period, person, total, carried) VALUES (?, ?, ?, ?, ?)", sheet,
                name, person, due, carried.getOrDefault(person, BigDecimal.ZERO.setScale(2))));
        return true;
    }

    /**
     * Fixes each pool member's cut for the period (by pool, then by member key: the person's id or pool:<name>; ""
     * when they have none), replacing any fixed before.
     */
    public void fixPoolCuts(String sheet, String name, Map<String, Map<String, String>> cuts) {
        jdbc.update("DELETE FROM period_pool_cut WHERE sheet = ? AND period = ?", sheet, name);
        cuts.forEach((pool, members) -> members.forEach((member, cut) -> jdbc.update(
                "INSERT INTO period_pool_cut (sheet, period, pool, member, cut) VALUES (?, ?, ?, ?, ?)", sheet, name,
                pool, member, cut)));
    }

    /** Each fixed pool cut on the sheet, by period name, then pool, then member key (see {@link #fixPoolCuts}). */
    public Map<String, Map<String, Map<String, String>>> poolCuts(String sheet) {
        Map<String, Map<String, Map<String, String>>> cuts = new HashMap<>();
        jdbc.query("SELECT period, pool, member, cut FROM period_pool_cut WHERE sheet = ?",
                (rs) -> {
                    cuts.computeIfAbsent(rs.getString("period"), (k) -> new HashMap<>())
                            .computeIfAbsent(rs.getString("pool"), (k) -> new HashMap<>())
                            .put(rs.getString("member"), rs.getString("cut"));
                }, sheet);
        return cuts;
    }

    /** Reopens the closed or soft-closed period, dropping its fixed due-totals, carried figures and pool cuts; false when it was neither, is locked (or is gone). */
    public boolean reopen(String sheet, String name) {
        if (jdbc.update("UPDATE period SET closed = FALSE, soft = FALSE, closed_total = NULL WHERE sheet = ? AND name = ?"
                + " AND (closed OR soft) AND NOT locked",
                sheet, name) != 1) {
            return false;
        }
        jdbc.update("DELETE FROM period_person_total WHERE sheet = ? AND period = ?", sheet, name);
        jdbc.update("DELETE FROM period_pool_cut WHERE sheet = ? AND period = ?", sheet, name);
        return true;
    }

    /** Locks or unlocks the period; false when it already was (or is gone). */
    public boolean lock(String sheet, String name, boolean locked) {
        return jdbc.update("UPDATE period SET locked = ? WHERE sheet = ? AND name = ? AND locked <> ?", locked, sheet,
                name, locked) == 1;
    }
}
