108	    /**
109	     * The holder's part of this claim: its amount times the share divided by 100, times the rate of the holder's own
110	     * grade in force on its date (of the rates it sees), divided by 100, rounded by the mode; null (0.00) when that
111	     * grade has no rate. A SETTLED claim keeps its parts as frozen: the share of its due (null for none).
112	     */
113	    public BigDecimal partOf(ClaimShare share, BigDecimal due, String holderGrade, List<Rate> rates, RoundingMode rounding) {
114	        if (status == ClaimStatus.SETTLED) {
115	            return due == null ? null : share.partOf(due);
116	        }
117	        String pct = holderGrade == null ? null : Rate.on(Rate.seenBy(rates, added), holderGrade, LocalDate.parse(date));
118	        return pct == null ? null
119	                : new BigDecimal(amount).multiply(new BigDecimal(share.share())).movePointLeft(2)
120	                        .multiply(new BigDecimal(pct)).movePointLeft(2).setScale(2, rounding);
121	    }
