123	    /**
124	     * The holders' parts (see {@link #partOf}) added up: what the claim's own person's due-total does not count of its
125	     * due; each holder's grade on its date given by the person.
126	     */
127	    public BigDecimal sharedPart(BigDecimal due, Function<Long, String> holderGrade, List<Rate> rates, RoundingMode rounding) {
128	        BigDecimal parts = BigDecimal.ZERO.setScale(2);
129	        for (ClaimShare share : shares == null ? List.<ClaimShare>of() : shares) {
130	            BigDecimal part = partOf(share, due, holderGrade.apply(share.person()), rates, rounding);
131	            parts = part == null ? parts : parts.add(part);
132	        }
133	        return parts;
