179	    /**
180	     * The status this claim had at the end of the day, as its status log records it (the last line on or before it);
181	     * null when it was not yet added then. A claim kept from before the log (no lines) has its status now.
182	     */
183	    public ClaimStatus statusOn(LocalDate end) {
184	        if (log == null || log.isEmpty()) {
185	            return status;
186	        }
187	        ClaimStatus then = null;
188	        for (ClaimLogLine line : log) {
189	            if (!LocalDate.parse(line.on()).isAfter(end)) {
190	                then = line.status();
191	            }
192	        }
193	        return then;
194	    }
