201	    /**
202	     * Whether this claim keeps a figure whatever the rates: fixed when settled, or bound by a statement (a claim
203	     * settled or bound when its grade had no rate keeps none).
204	     */
205	    public boolean fixed() {
206	        return settledDue != null || (bound() && statedDue != null);
207	    }
