209	    /**
210	     * This claim's due: the due fixed when settled; else the due its statement bound (as shown then, late charge
211	     * included); else its floored figure (the greater of the sheet's floor in force on its date and its {@link #figure})
212	     * plus, while it is overdue, its late charge on that floored figure (a correction has no floor and no charge); null
213	     * when there is no figure.
214	     */
215	    public BigDecimal due(List<Rate> rates, String grade, Dated floor, Late late) {
216	        BigDecimal figure = figure(rates, grade, floor, late.rounding(this));
217	        if (figure == null || settledDue != null || bound() || correction()) {
218	            return figure;
219	        }
220	        BigDecimal floored = figure.max(floor.on(date));
221	        return floored.add(late.charge(this, grade, floored));
222	    }
223	
224	    /**
225	     * This claim's figure: the due fixed when settled, else the due its statement bound (as shown, late charge
226	     * included), else
227	     * its amount at the grade's rate in force on its date, of the rates it sees (the floor is applied before the late charge, in {@link #due}); null when
228	     * there is none.
229	     */
230	    public BigDecimal figure(List<Rate> rates, String grade, Dated floor) {
231	        return figure(rates, grade, floor, RoundingMode.HALF_EVEN);
232	    }
233	
234	    /** This claim's {@link #figure}, its live figure rounded by the mode. */
235	    public BigDecimal figure(List<Rate> rates, String grade, Dated floor, RoundingMode rounding) {
236	        if (settledDue != null) {
237	            return new BigDecimal(settledDue);
238	        }
239	        if (bound()) {
240	            return statedDue == null ? null : new BigDecimal(statedDue);
241	        }
242	        return Rate.due(amount, Rate.on(Rate.seenBy(rates, added), grade, LocalDate.parse(date)), rounding);
243	    }
