361	    public boolean share(String sheet, long id, ClaimStatus status, int was, long person, BigDecimal share) {
362	        // Locks the claim's row, so two shares at once are taken one after the other.
363	        if (jdbc.update("UPDATE claim SET status = status WHERE sheet = ? AND id = ? AND status = ?", sheet, id, status.name()) != 1) {
364	            return false;
