366	        Integer now = jdbc.queryForObject("SELECT COUNT(*) FROM claim_share WHERE sheet = ? AND claim = ?", Integer.class, sheet, id);
367	        if (now == null || now != was) {
368	            return false;
369	        }
370	        jdbc.update("INSERT INTO claim_share (sheet, claim, person, share) VALUES (?, ?, ?, ?)", sheet, id, person, share);
371	        return true;
372	    }
