727	    /**
728	     * Takes the next number in the sheet's period of the name ("" for the claims in no period): 1 first, then 2,
729	     * and so on, each period counting on its own. Locked as {@link #nextNumber}.
730	     */
731	    public int nextPeriodNumber(String sheet, String period) {
732	        while (true) {
733	            if (jdbc.update("UPDATE claim_period_number SET last_number = last_number + 1 WHERE sheet = ? AND period = ?",
734	                    sheet, period) == 1) {
735	                return jdbc.queryForObject("SELECT last_number FROM claim_period_number WHERE sheet = ? AND period = ?",
736	                        Integer.class, sheet, period);
737	            }
738	            try {
739	                jdbc.update("INSERT INTO claim_period_number (sheet, period, last_number) VALUES (?, ?, 1)", sheet, period);
740	                return 1;
741	            } catch (DuplicateKeyException raced) {
742	                // Another user took the period's first number at the same moment: take the one after it.
743	            }
744	        }
745	    }
746	
747	    /**
748	     * Takes the next number of the sheet-wide sequence the sheet shares with the other sheets of its tree: the one
749	     * after the last number given on any of them (1 when none has given one), recorded as the sheet's last number.
750	     * The counter rows of the whole tree stay locked until the transaction ends, so two claims opened at once
751	     * anywhere in the tree get different numbers.
752	     */
753	    public int nextNumber(String sheet, List<String> tree) {
754	        try {
755	            jdbc.update("INSERT INTO claim_number (sheet, last_number) VALUES (?, 0)", sheet);
756	        } catch (DuplicateKeyException exists) {
757	            // The sheet has given a number already: its counter is in place.
758	        }
759	        java.util.TreeSet<String> sheets = new java.util.TreeSet<>(tree);
760	        sheets.add(sheet);
761	        String in = String.join(", ", java.util.Collections.nCopies(sheets.size(), "?"));
762	        List<Integer> lasts = jdbc.queryForList("SELECT last_number FROM claim_number WHERE sheet IN (" + in
763	                + ") ORDER BY sheet FOR UPDATE", Integer.class, sheets.toArray());
764	        int next = lasts.stream().mapToInt(Integer::intValue).max().orElse(0) + 1;
765	        jdbc.update("UPDATE claim_number SET last_number = ? WHERE sheet = ?", next, sheet);
766	        return next;
767	    }
768	
769	    /**
770	     * Takes the next number of the fiscal year's sequence (FY<yyyy>) the sheet shares with the other sheets of its
771	     * tree: the one after the last number given in that year on any of them (1 when none has given one), recorded as
772	     * the sheet's last number in it. Locked as {@link #nextNumber}.
773	     */
774	    public int nextFiscalYearNumber(String sheet, List<String> tree, String fy) {
775	        try {
776	            jdbc.update("INSERT INTO claim_fy_number (sheet, fy, last_number) VALUES (?, ?, 0)", sheet, fy);
777	        } catch (DuplicateKeyException exists) {
778	            // The sheet has given a number in this fiscal year already: its counter is in place.
779	        }
780	        java.util.TreeSet<String> sheets = new java.util.TreeSet<>(tree);
781	        sheets.add(sheet);
782	        String in = String.join(", ", java.util.Collections.nCopies(sheets.size(), "?"));
783	        List<Object> args = new java.util.ArrayList<>();
784	        args.add(fy);
785	        args.addAll(sheets);
786	        List<Integer> lasts = jdbc.queryForList("SELECT last_number FROM claim_fy_number WHERE fy = ? AND sheet IN (" + in
787	                + ") ORDER BY sheet FOR UPDATE", Integer.class, args.toArray());
788	        int next = lasts.stream().mapToInt(Integer::intValue).max().orElse(0) + 1;
789	        jdbc.update("UPDATE claim_fy_number SET last_number = ? WHERE sheet = ? AND fy = ?", next, sheet, fy);
790	        return next;
791	    }
792	}
