20	import org.springframework.stereotype.Service;
21	
22	/** Moves a claim to the status a change takes it to, refusing a change its status does not allow; shared by a
23	 *  claim's own status buttons and the bulk actions. */
24	@Service
25	public class ClaimStatusChanger {
26	
27	    /** How many days after its settlement a steward may still void a SETTLED claim. */
28	    public static final int VOID_SETTLED_DAYS = 7;
29	
30	    private final Claims claims;
31	    private final People people;
32	    private final Rates rates;
33	    private final Periods periods;
34	    private final Roles roles;
35	    private final Settings settings;
36	    private final SheetClock clock;
37	    private final Audit audit;
38	    private final Rollup rollup;
39	    private final ClaimLog log;
40	    private final Watches watches;
41	    private final SheetArchive archive;
42	    private final VoidReasons voidReasons;
43	
44	    public ClaimStatusChanger(Claims claims, People people, Rates rates, Periods periods, Roles roles, Settings settings,
45	            SheetClock clock, Audit audit, Rollup rollup, ClaimLog log, Watches watches, SheetArchive archive,
46	            VoidReasons voidReasons) {
47	        this.claims = claims;
48	        this.people = people;
49	        this.rates = rates;
50	        this.periods = periods;
51	        this.roles = roles;
52	        this.settings = settings;
53	        this.clock = clock;
54	        this.audit = audit;
55	        this.rollup = rollup;
56	        this.log = log;
57	        this.watches = watches;
58	        this.archive = archive;
59	        this.voidReasons = voidReasons;
60	    }
61	
62	    /** Applies the change to the claim, writing nothing when it is refused. */
63	    public void change(String sheet, String user, Claim claim, ClaimStatusChange requested)
64	            throws InvalidClaimStatusChangeException {
65	        change(sheet, user, claim, requested, null);
66	    }
67	
68	    /** Applies the change to the claim (a reject gives its reason, a void the one chosen from the sheet's void reasons),
69	     *  writing nothing when it is refused. */
70	    public void change(String sheet, String user, Claim claim, ClaimStatusChange requested, String reason)
71	            throws InvalidClaimStatusChangeException {
72	        change(sheet, user, claim, requested, reason, true, null, null);
73	    }
74	
75	    /** Settles the claim as the settle button does, freezing the due it had at the end of the date (on or before the
76	     *  sheet's today, worked out by the caller) in place of today's; writes nothing when it is refused. */
77	    public void settleAsOf(String sheet, String user, Claim claim, LocalDate on, BigDecimal due)
78	            throws InvalidClaimStatusChangeException {
79	        change(sheet, user, claim, ClaimStatusChange.SETTLE, null, true, on, due);
80	    }
81	
82	    /** Settles the claim just split off another to part-settle it, as the settle button does (to PENDING when the
83	     *  clerk limit says so), save that the four-eyes rules and the proof rule were judged on the claim it was split
84	     *  off, so are not judged again on it (whose opener is the user); writes nothing when it is refused. */
85	    public void settlePart(String sheet, String user, Claim part) throws InvalidClaimStatusChangeException {
86	        change(sheet, user, part, ClaimStatusChange.SETTLE, null, false, null, null);
87	    }
88	
89	    private void change(String sheet, String user, Claim claim, ClaimStatusChange requested, String reason,
90	            boolean ownRules, LocalDate on, BigDecimal dueOn) throws InvalidClaimStatusChangeException {
91	        requested = vet(sheet, user, claim, requested, reason, ownRules);
92	        String voidReason = requested == ClaimStatusChange.VOID && voidReasons.any(sheet) ? reason.trim() : null;
93	        Person person = people.find(sheet, claim.person());
94	        Rollup.Snapshot before = rollup.take(sheet);
95	        ClaimStatus next = claim.status().after(requested);
96	        // Conditional on the status read, so a concurrent change by another user is refused, not overwritten.
97	        if (next == null || !claims.changeStatus(sheet, claim.id(), claim.status(), next)) {
98	            throw new InvalidClaimStatusChangeException(
99	                    "A " + claim.status() + " claim does not allow " + requested.name().toLowerCase());
100	        }
101	        // Settling (or approving) gives the next number (FY<yyyy>-<n>) of its fiscal year its sheet's tree shares, or,
102	        // while the sheet numbers by period from on or before its today, the next number in the claim's period (X for
103	        // none); an OPEN, PENDING or REVIEW claim has none. A claim numbered already keeps its number, and a voided
104	        // claim keeps the number it had (never reused).
105	        Claim changed = claim;
106	        if ((requested == ClaimStatusChange.SETTLE || requested == ClaimStatusChange.APPROVE)
107	                && claim.shownNumber() == null) {
108	            changed = number(sheet, claim);
109	        }
110	        // Who opened it is the user who pressed open, also when it went to REVIEW first (not the reviewing steward).
111	        if (requested == ClaimStatusChange.OPEN || requested == ClaimStatusChange.HOLD_FOR_REVIEW) {
112	            claims.setOpenedBy(sheet, claim.id(), user);
113	        }
114	        String fields = changed.statusAuditFields(person.name());
115	        // Settling (or approving a PENDING claim) fixes the due at the person's grade rate in force on the claim's date (or the figure its
116	        // statement bound), with its late charge frozen in; with no rate there is nothing to fix, so it stays live.
117	        if (requested == ClaimStatusChange.SETTLE || requested == ClaimStatusChange.APPROVE) {
118	            // Settled as of a date, the due is the one it had at the end of that day.
119	            boolean asOf = on != null && requested == ClaimStatusChange.SETTLE;
120	            BigDecimal due = asOf ? dueOn : claim.due(rates.list(sheet), person.gradeOn(claim.date()), settings.floor(sheet),
121	                    settings.late(sheet, clock.today(sheet)));
122	            claims.setSettledDue(sheet, claim.id(), due);
123	            fields += " due=" + (due == null ? "n/a" : due.toPlainString());
124	            if (asOf) {
125	                fields += " on=" + on;
126	            }
127	        }
128	        // Voiding a SETTLED claim reverses its frozen figure out of every total.
129	        if (requested == ClaimStatusChange.VOID && claim.status() == ClaimStatus.SETTLED) {
130	            fields += " reversed=" + (claim.settledDue() == null ? "n/a" : claim.settledDue());
131	        }
132	        if (requested == ClaimStatusChange.REJECT) {
133	            fields += " reason=" + reason.trim();
134	        }
135	        if (voidReason != null) {
136	            voidReasons.voided(sheet, claim.id(), voidReason);
137	            fields += " reason=" + voidReason;
138	        }
139	        log.record(sheet, user, claim.id());
140	        // A review is written (naming the claim) then the open it makes.
141	        if (requested == ClaimStatusChange.REVIEW) {
142	            audit.record(requested.event() + " sheet=" + sheet + " by=" + user + " " + claim.statusAuditFields(person.name()));
143	            audit.record(ClaimStatusChange.OPEN.event() + " sheet=" + sheet + " by=" + user + " " + fields);
144	        } else {
145	            audit.record(requested.event() + " sheet=" + sheet + " by=" + user + " " + fields);
146	        }
147	        // Settling or approving tells each user watching the person, before the rollup lines.
148	        if (requested == ClaimStatusChange.SETTLE || requested == ClaimStatusChange.APPROVE) {
149	            watches.notify(sheet, user, person.id(), person.name(), changed.shownNumber());
150	        }
151	        rollup.record(sheet, user, before);
152	    }
153	
154	    /** Refuses the change the user may not make to the claim as it is now, writing nothing; otherwise gives the change
155	     *  it makes (a clerk's settle above the clerk limit is a move to PENDING). */
156	    public ClaimStatusChange vet(String sheet, String user, Claim claim, ClaimStatusChange requested, String reason)
157	            throws InvalidClaimStatusChangeException {
158	        return vet(sheet, user, claim, requested, reason, true);
159	    }
160	
161	    /** As {@link #vet}, judging the four-eyes rules and the proof rule on the claim only when ownRules. */
162	    /** Whether the user is the approver of the claim's person. */
163	    private boolean approverOf(String sheet, String user, Claim claim) {
164	        Person person = people.find(sheet, claim.person());
165	        return person != null && user.equals(person.approver());
166	    }
167	
168	    private ClaimStatusChange vet(String sheet, String user, Claim claim, ClaimStatusChange requested, String reason,
169	            boolean ownRules) throws InvalidClaimStatusChangeException {
170	        // A viewer changes nothing.
171	        if (Role.VIEWER.equals(roles.of(sheet, user))) {
172	            throw new InvalidClaimStatusChangeException("A viewer cannot change a claim");
173	        }
174	        if (archive.archived(sheet)) {
175	            throw new InvalidClaimStatusChangeException("An archived sheet cannot change");
176	        }
177	        // The permission matrix says which roles open, settle and void a claim.
178	        if ((requested == ClaimStatusChange.OPEN || requested == ClaimStatusChange.SETTLE || requested == ClaimStatusChange.VOID)
179	                && !settings.permits(sheet, requested.name().toLowerCase(), roles.of(sheet, user))) {
180	            throw new InvalidClaimStatusChangeException("Your role may not " + requested.name().toLowerCase() + " a claim");
181	        }
182	        // While its person's flag is in force (the sheet's today on or before its until-date) only a steward opens a claim.
183	        if (requested == ClaimStatusChange.OPEN && !Role.STEWARD.equals(roles.of(sheet, user))) {
184	            Person flagged = people.find(sheet, claim.person());
185	            if (flagged != null && flagged.flagged()) {
186	                throw new InvalidClaimStatusChangeException(
187	                        "Only a steward may open a claim of " + flagged.name() + " while flagged: " + flagged.flagReason());
188	            }
189	        }
190	        // Only a steward reviews a REVIEW claim, opening it.
191	        if (requested == ClaimStatusChange.REVIEW && !Role.STEWARD.equals(roles.of(sheet, user))) {
192	            throw new InvalidClaimStatusChangeException("Only a steward reviews a claim");
193	        }
194	        if (periods.closedOn(sheet, LocalDate.parse(claim.dueBy()))) {
195	            throw new InvalidClaimStatusChangeException("A claim due inside a closed period cannot change status");
196	        }
197	        // A steward voids a SETTLED claim only within 7 days of its settlement (its status log's last SETTLED date).
198	        if (requested == ClaimStatusChange.VOID && claim.status() == ClaimStatus.SETTLED) {
199	            if (!Role.STEWARD.equals(roles.of(sheet, user))) {
200	                throw new InvalidClaimStatusChangeException("Only a steward voids a settled claim");
201	            }
202	            LocalDate settled = claim.settledOn();
203	            LocalDate today = clock.today(sheet);
204	            if (settled == null || today.isBefore(settled) || today.isAfter(settled.plusDays(VOID_SETTLED_DAYS))) {
205	                throw new InvalidClaimStatusChangeException(
206	                        "A settled claim may be voided only within " + VOID_SETTLED_DAYS + " days of its settlement");
207	            }
208	        }
209	        // A DELETED claim is restored only on the sheet's today it was deleted (its status log's last DELETED date).
210	        if (requested == ClaimStatusChange.RESTORE && claim.status() == ClaimStatus.DELETED
211	                && !clock.today(sheet).equals(claim.deletedOn())) {
212	            throw new InvalidClaimStatusChangeException("A deleted claim may be restored only on the day it was deleted");
213	        }
214	        if (requested == ClaimStatusChange.SETTLE && claim.deferred()) {
215	            throw new InvalidClaimStatusChangeException("A deferred claim cannot be settled until its date");
216	        }
217	        // Four eyes: the user who opened a claim may not settle it, nor approve it.
218	        if (ownRules && (requested == ClaimStatusChange.SETTLE || requested == ClaimStatusChange.APPROVE)
219	                && user.equals(claim.openedBy())) {
220	            throw new InvalidClaimStatusChangeException("The user who opened a claim cannot settle or approve it");
221	        }
222	        // Nor may the user who last edited it.
223	        if (ownRules && (requested == ClaimStatusChange.SETTLE || requested == ClaimStatusChange.APPROVE)
224	                && user.equals(claims.editedBy(sheet, claim.id()))) {
225	            throw new InvalidClaimStatusChangeException("The user who last edited a claim cannot settle or approve it");
226	        }
227	        // Only a steward, or the approver of the claim's person, approves or rejects a PENDING claim; a reject gives a reason.
228	        if ((requested == ClaimStatusChange.APPROVE || requested == ClaimStatusChange.REJECT)
229	                && !Role.STEWARD.equals(roles.of(sheet, user)) && !approverOf(sheet, user, claim)) {
230	            throw new InvalidClaimStatusChangeException("Only a steward approves or rejects a claim");
231	        }
232	        if (requested == ClaimStatusChange.REJECT && (reason == null || reason.isBlank())) {
233	            throw new InvalidClaimStatusChangeException("A reject needs a reason");
234	        }
235	        // While the sheet has void reasons, a void needs one chosen from them (with none, a void takes no reason).
236	        if (requested == ClaimStatusChange.VOID && voidReasons.any(sheet)) {
237	            String voidReason = reason == null ? "" : reason.trim();
238	            if (voidReason.isEmpty() || !voidReasons.has(sheet, voidReason)) {
239	                throw new InvalidClaimStatusChangeException("A void needs a reason from the sheet's void reasons");
240	            }
241	        }
242	        Person person = people.find(sheet, claim.person());
243	        // A claim whose due is above the proof threshold in force on its date (its person's grade's then when it has
244	        // one, else the sheet's) is settled or approved only once it has
245	        // a proof (a due of n/a is above no threshold); checked before the clerk limit, so it never goes to PENDING.
246	        if (ownRules && (requested == ClaimStatusChange.SETTLE || requested == ClaimStatusChange.APPROVE)) {
247	            BigDecimal threshold = settings.proofThreshold(sheet, person.gradeOn(claim.date()),
248	                    LocalDate.parse(claim.date()));
249	            // While the sheet has proof kinds, it needs one proof of each of them, not just one.
250	            List<String> kinds = settings.proofKinds(sheet);
251	            boolean proven = kinds.isEmpty() ? claim.proofs() > 0 : kinds.stream().allMatch((k) -> claim.proofsOf(k) > 0);
252	            if (threshold != null && !proven) {
253	                BigDecimal due = claim.due(rates.list(sheet), person.gradeOn(claim.date()), settings.floor(sheet),
254	                        settings.late(sheet, clock.today(sheet)));
255	                if (due != null && due.compareTo(threshold) > 0) {
256	                    throw new InvalidClaimStatusChangeException(
257	                            "A claim whose due is above the proof threshold needs a proof (one of each of the sheet's proof kinds) before it is settled or approved");
258	                }
259	            }
260	        }
261	        // A claim whose due is above the note threshold in force on its date is opened only with a note (a due of n/a
262	        // is above no threshold).
263	        if (requested == ClaimStatusChange.OPEN && (claim.note() == null || claim.note().isBlank())) {
264	            BigDecimal threshold = settings.noteThreshold(sheet, LocalDate.parse(claim.date()));
265	            if (threshold != null) {
266	                BigDecimal due = claim.due(rates.list(sheet), person.gradeOn(claim.date()), settings.floor(sheet),
267	                        settings.late(sheet, clock.today(sheet)));
268	                if (due != null && due.compareTo(threshold) > 0) {
269	                    throw new InvalidClaimStatusChangeException(
270	                            "A claim whose due is above the note threshold needs a note before it is opened");
271	                }
272	            }
273	        }
274	        // A clerk settles only a due at or below the clerk limit in force on the claim's date (its person's grade's
275	        // when it has one, else the sheet's; a due of n/a is within any limit); above
276	        // it the claim goes to PENDING for a steward to approve. A steward settles anything.
277	        if (requested == ClaimStatusChange.SETTLE && claim.status() == ClaimStatus.OPEN
278	                && (Role.CLERK.equals(roles.of(sheet, user)) || Role.RESTRICTED.equals(roles.of(sheet, user)))) {
279	            BigDecimal limit = settings.clerkLimit(sheet, person.gradeOn(claim.date()), LocalDate.parse(claim.date()));
280	            BigDecimal due = claim.due(rates.list(sheet), person.gradeOn(claim.date()), settings.floor(sheet),
281	                    settings.late(sheet, clock.today(sheet)));
282	            if (limit != null && due != null && due.compareTo(limit) > 0) {
283	                requested = ClaimStatusChange.PEND;
284	            }
285	        }
286	        // A claim whose due is above the review threshold in force on its date goes to REVIEW when opened, for a
287	        // steward to review (a due of n/a is above no threshold).
288	        if (requested == ClaimStatusChange.OPEN && claim.status() == ClaimStatus.DRAFT) {
289	            BigDecimal threshold = settings.reviewThreshold(sheet, LocalDate.parse(claim.date()));
290	            if (threshold != null) {
291	                BigDecimal due = claim.due(rates.list(sheet), person.gradeOn(claim.date()), settings.floor(sheet),
292	                        settings.late(sheet, clock.today(sheet)));
293	                if (due != null && due.compareTo(threshold) > 0) {
294	                    requested = ClaimStatusChange.HOLD_FOR_REVIEW;
295	                }
296	            }
297	        }
298	        if (claim.status().after(requested) == null) {
299	            throw new InvalidClaimStatusChangeException(
300	                    "A " + claim.status() + " claim does not allow " + requested.name().toLowerCase());
301	        }
302	        // A period with a cap lets each person have at most that many OPEN or PENDING claims due inside it.
303	        if (requested == ClaimStatusChange.OPEN || requested == ClaimStatusChange.REVIEW) {
304	            // The sheet's maximum lets each person have at most that many OPEN or PENDING claims in all.
305	            Integer max = settings.maxOpen(sheet);
306	            if (max != null) {
307	                long held = claims.list(sheet).stream()
308	                        .filter((c) -> c.person() == claim.person() && c.id() != claim.id())
309	                        .filter((c) -> c.status() == ClaimStatus.OPEN || c.status() == ClaimStatus.PENDING)
310	                        .count();
311	                if (held >= max) {
312	                    throw new InvalidClaimStatusChangeException("A person may have at most " + max + " open claims");
313	                }
314	            }
315	            Period period = periods.on(sheet, LocalDate.parse(claim.dueBy()));
316	            if (period != null && period.cap() != null) {
317	                long held = claims.list(sheet).stream()
318	                        .filter((c) -> c.person() == claim.person() && c.id() != claim.id())
319	                        .filter((c) -> c.status() == ClaimStatus.OPEN || c.status() == ClaimStatus.PENDING)
320	                        .filter((c) -> c.dueBy().compareTo(period.from()) >= 0 && c.dueBy().compareTo(period.to()) <= 0)
321	                        .count();
322	                if (held >= period.cap()) {
323	                    throw new InvalidClaimStatusChangeException("A person may have at most " + period.cap()
324	                            + " open claims in period " + period.name());
325	                }
326	            }
327	        }
328	        return requested;
329	    }
330	
331	    /**
332	     * Gives a settling claim the next number (FY<yyyy>-<n>) of its due-by's fiscal year in the sequence its sheet shares with its tree, or, while the sheet numbers by period from on or before its
333	     * today, the next number in the claim's period (X for none); returns the claim so numbered.
334	     */
335	    public Claim number(String sheet, Claim claim) {
336	        LocalDate from = settings.periodNumberingFrom(sheet);
337	        if (from != null && !clock.today(sheet).isBefore(from)) {
338	            String period = periods.nameOn(sheet, LocalDate.parse(claim.dueBy()));
339	            String key = period == null ? "" : period;
340	            Claim numbered = claim.withPeriodNumber((period == null ? "X" : period) + "-" + claims.nextPeriodNumber(sheet, key));
341	            claims.setPeriodNumber(sheet, claim.id(), numbered.periodNumber());
342	            return numbered;
343	        }
344	        // Sheet-wide numbering restarts each fiscal year (of the due-by, the date that places it in a period):
345	        // FY<yyyy>-<n>, kept as the number it shows.
346	        LocalDate dueBy = LocalDate.parse(claim.dueBy());
347	        int start = settings.fiscalStartMonth(sheet);
348	        String fy = "FY" + (dueBy.getMonthValue() >= start ? dueBy.getYear() : dueBy.getYear() - 1);
349	        Claim numbered = claim.withPeriodNumber(fy + "-" + claims.nextFiscalYearNumber(sheet, settings.wholeTree(sheet), fy));
350	        claims.setPeriodNumber(sheet, claim.id(), numbered.periodNumber());
351	        return numbered;
352	    }
353	}
