364	/** Moves the claim to the status the change takes it to, refusing a change its status does not allow; a settle
365	 *  with a date is as of that day. */
366	public class ApplyClaimStatus {
367	    public void apply(@PathVariable("sheet") String sheet, @PathVariable("change") String change,
368	            @RequestParam("user") String user, @RequestBody ClaimStatusRequest body, @Val Claim claim,
369	            ClaimStatusChanger changer, Claims claims, ClaimDueAsOf dueAsOf, SheetClock clock) throws InvalidClaimStatusChangeException {
370	        ClaimStatusChange requested = ClaimStatusChange.of(change);
371	        if (requested == null) {
372	            throw new InvalidClaimStatusChangeException("No such status change: " + change);
373	        }
374	        String on = body == null || body.on() == null ? "" : body.on().trim();
375	        if (requested == ClaimStatusChange.SETTLE && !on.isEmpty()) {
376	            // Settled as of a date on or before the sheet's today, at the due the claim had at the end of it.
377	            LocalDate date;
378	            try {
379	                date = LocalDate.parse(on);
380	            } catch (DateTimeParseException e) {
381	                throw new InvalidClaimStatusChangeException("Not a valid settle date: " + on);
382	            }
383	            if (date.isAfter(clock.today(sheet))) {
384	                throw new InvalidClaimStatusChangeException("A claim cannot be settled as of a date after today");
385	            }
386	            ClaimDueAsOf.Then then = dueAsOf.on(sheet, claim.id(), date);
387	            if (!then.existed()) {
388	                throw new InvalidClaimStatusChangeException("The claim did not exist on " + date);
389	            }
390	            changer.settleAsOf(sheet, user, claim, date, then.due());
391	        } else {
392	            changer.change(sheet, user, claim, requested, body == null ? null : body.reason());
393	        }
394	        if (requested == ClaimStatusChange.SETTLE) {
395	            // Settled one at a time: no longer part of a bulk settle batch.
396	            claims.setBatch(sheet, claim.id(), null);
397	        }
398	    }
399	}
