410	/**
411	 * Holds an OPEN or PENDING claim, or releases it when held: while held and not bound by a statement it counts in no
412	 * due figure (it stays in claimed), as a held person's claims do. Refuses any other status.
413	 */
414	public class HoldClaim {
415	    public void hold(@PathVariable("sheet") String sheet, @RequestParam("user") String user, @Val Claim claim,
416	            Claims claims, People people, Audit audit, Rollup rollup) throws InvalidClaimStatusChangeException {
417	        if (claim.status() != ClaimStatus.OPEN && claim.status() != ClaimStatus.PENDING) {
418	            throw new InvalidClaimStatusChangeException("A " + claim.status() + " claim cannot be held or released");
419	        }
420	        Person person = people.find(sheet, claim.person());
421	        Rollup.Snapshot before = rollup.take(sheet);
422	        boolean held = !claim.held();
423	        // Conditional on the status and held flag read, so a concurrent change is refused.
424	        if (!claims.hold(sheet, claim.id(), claim.status(), held)) {
425	            throw new InvalidClaimStatusChangeException("The claim changed since it was read");
426	        }
427	        audit.record((held ? "CLAIM_HELD" : "CLAIM_RELEASED") + " sheet=" + sheet + " by=" + user + " "
428	                + claim.statusAuditFields(person.name()));
429	        rollup.record(sheet, user, before);
430	    }
431	}
