515	/**
516	 * Defers an OPEN claim dated outside a closed period until a date after the sheet's today: until the sheet's today
517	 * reaches it the claim counts in no total, is not overdue, cannot be settled and is left unbound by a statement. A claim a
518	 * statement binds stays in the totals and counts, and can be settled, while bound: the deferral takes effect only once
519	 * the binding ends (the statement is cancelled, or the next one leaves it unbound).
520	 */
521	public class DeferClaim {
522	    public void defer(@PathVariable("sheet") String sheet, @RequestParam("user") String user, @Val LocalDate until,
523	            @Val Claim claim, Claims claims, People people, Periods periods, SheetClock clock, Audit audit,
524	            Rollup rollup) throws InvalidClaimStatusChangeException {
525	        if (claim.status() != ClaimStatus.OPEN) {
526	            throw new InvalidClaimStatusChangeException("A " + claim.status() + " claim cannot be deferred");
527	        }
528	        if (!until.isAfter(clock.today(sheet))) {
529	            throw new InvalidClaimStatusChangeException("A claim is deferred to a date after the sheet's today");
530	        }
531	        if (periods.closedOn(sheet, LocalDate.parse(claim.dueBy()))) {
532	            throw new InvalidClaimStatusChangeException("A claim due inside a closed period cannot be deferred");
533	        }
534	        Person person = people.find(sheet, claim.person());
535	        Rollup.Snapshot before = rollup.take(sheet);
536	        // Conditional on the status read, so a concurrent change by another user is refused, not overwritten.
537	        if (!claims.defer(sheet, claim.id(), until)) {
538	            throw new InvalidClaimStatusChangeException("The claim changed since it was read");
539	        }
540	        audit.record("CLAIM_DEFERRED sheet=" + sheet + " by=" + user + " " + claim.statusAuditFields(person.name())
541	                + " until=" + until);
542	        rollup.record(sheet, user, before);
543	    }
544	}
