547	import java.math.BigDecimal;
548	import net.officefloor.hq.app.Audit;
549	import net.officefloor.plugin.variable.Val;
550	import org.springframework.transaction.PlatformTransactionManager;
551	import org.springframework.transaction.TransactionDefinition;
552	import org.springframework.transaction.support.TransactionTemplate;
553	import org.springframework.web.bind.annotation.PathVariable;
554	import org.springframework.web.bind.annotation.RequestParam;
555	
556	/**
557	 * Part-settles an OPEN claim: splits the amount off it as the Split button does, then settles the new claim as the
558	 * Settle button does (to PENDING when the clerk limit says so). The four-eyes rules and the proof rule are judged on
559	 * the claim part-settled, not the new one (whose opener is the user). Any refusal refuses the whole action: its
560	 * savepoint rolls back and the audit records held meanwhile are dropped.
561	 */
562	public class SettlePartClaim {
563	    public void settle(@PathVariable("sheet") String sheet, @RequestParam("user") String user, @Val BigDecimal amount,
564	            @Val Claim claim, ClaimSplitter splitter, ClaimStatusChanger changer, Claims claims, Audit audit,
565	            PlatformTransactionManager transactions) throws InvalidClaimStatusChangeException {
566	        TransactionTemplate transaction = new TransactionTemplate(transactions);
567	        transaction.setPropagationBehavior(TransactionDefinition.PROPAGATION_NESTED);
568	        audit.hold();
569	        try {
570	            transaction.execute((status) -> {
571	                try {
572	                    // Judged on the claim part-settled first, so its opener and editor may not settle part of it.
573	                    changer.vet(sheet, user, claim, ClaimStatusChange.SETTLE, null);
574	                    Claim part = splitter.split(sheet, user, claim, amount);
575	                    changer.settlePart(sheet, user, part);
576	                } catch (InvalidClaimStatusChangeException refused) {
577	                    throw new Refused(refused);
578	                }
579	                return null;
580	            });
581	        } catch (Refused refused) {
582	            audit.discard();
583	            throw refused.cause;
584	        } catch (RuntimeException failed) {
585	            audit.discard();
586	            throw failed;
587	        }
588	        audit.release();
589	    }
590	
591	    private static final class Refused extends RuntimeException {
592	        private final InvalidClaimStatusChangeException cause;
593	
594	        private Refused(InvalidClaimStatusChangeException cause) {
595	            super(cause);
596	            this.cause = cause;
597	        }
598	    }
599	}
