619	/**
620	 * A steward re-settles a SETTLED claim outside a closed period: its due is fixed again at the figure it would have
621	 * today as an OPEN claim bound by no statement (today's rates, grades, floor and late charge), and its status log
622	 * gains a SETTLED line.
623	 */
624	public class ResettleClaim {
625	    public void resettle(@PathVariable("sheet") String sheet, @RequestParam("user") String user, @Val Claim claim,
626	            Claims claims, People people, Rates rates, Periods periods, Roles roles, Settings settings,
627	            SheetClock clock, Audit audit, Rollup rollup, ClaimLog log, Watches watches) throws InvalidClaimStatusChangeException {
628	        if (!Role.STEWARD.equals(roles.of(sheet, user))) {
629	            throw new InvalidClaimStatusChangeException("Only a steward re-settles a claim");
630	        }
631	        if (claim.status() != ClaimStatus.SETTLED) {
632	            throw new InvalidClaimStatusChangeException("A " + claim.status() + " claim cannot be re-settled");
633	        }
634	        if (periods.closedOn(sheet, LocalDate.parse(claim.dueBy()))) {
635	            throw new InvalidClaimStatusChangeException("A claim due inside a closed period cannot be re-settled");
636	        }
637	        Person person = people.find(sheet, claim.person());
638	        BigDecimal was = claim.settledDue() == null ? null : new BigDecimal(claim.settledDue());
639	        BigDecimal due = claim.asOpenUnbound().due(rates.list(sheet), person.gradeOn(claim.date()),
640	                settings.floor(sheet), settings.late(sheet, clock.today(sheet)));
641	        Rollup.Snapshot before = rollup.take(sheet);
642	        if (!claims.resettle(sheet, claim.id(), was, due)) {
643	            throw new InvalidClaimStatusChangeException("The claim changed since it was read");
644	        }
645	        log.record(sheet, user, claim.id());
646	        audit.record("CLAIM_RESETTLED sheet=" + sheet + " by=" + user + " " + claim.statusAuditFields(person.name())
647	                + " old=" + (was == null ? "n/a" : was.toPlainString())
648	                + " new=" + (due == null ? "n/a" : due.toPlainString()));
649	        watches.notify(sheet, user, person.id(), person.name(), claim.shownNumber());
650	        rollup.record(sheet, user, before);
651	    }
652	}
