44	    public PeriodCloser(Periods periods, Claims claims, People people, Rates rates, Settings settings, SheetClock clock,
45	            Audit audit, Pools pools) {
46	        this.pools = pools;
47	        this.periods = periods;
48	        this.claims = claims;
49	        this.people = people;
50	        this.rates = rates;
51	        this.settings = settings;
52	        this.clock = clock;
53	        this.audit = audit;
54	    }
