56	    /** Closes the period found open on the sheet; false when it was already closed. An auto close is audited auto=yes. */
57	    public boolean close(String sheet, String user, Period found, boolean auto) {
58	        return close(sheet, user, found, auto, false);
59	    }
60	
61	    /**
62	     * Closes the period found open (or soft-closed) on the sheet, or soft-closes it, fixing its figures afresh; false
63	     * when it was already closed, or for a soft close already soft-closed.
64	     */
65	    public boolean close(String sheet, String user, Period found, boolean auto, boolean soft) {
66	        LocalDate from = LocalDate.parse(found.from());
67	        LocalDate to = LocalDate.parse(found.to());
68	        Map<Long, Person> byId = people.list(sheet).stream().collect(Collectors.toMap(Person::id, (p) -> p));
69	        List<Rate> sheetRates = rates.list(sheet);
70	        Dated floor = settings.floor(sheet);
71	        Late late = settings.late(sheet, clock.today(sheet));
72	        BigDecimal total = BigDecimal.ZERO.setScale(2);
73	        Map<Long, BigDecimal> perPerson = new LinkedHashMap<>();
74	        byId.keySet().forEach((id) -> perPerson.put(id, BigDecimal.ZERO.setScale(2)));
75	        Map<Long, BigDecimal> carried = new LinkedHashMap<>(perPerson);
76	        periods.openings(sheet, found.name()).forEach((id, amount) -> {
77	            if (carried.containsKey(id)) {
78	                carried.merge(id, amount, BigDecimal::add);
79	            }
80	        });
81	        List<Period> sheetPeriods = periods.list(sheet);
82	        List<Claim> sheetClaims = claims.list(sheet);
83	        for (Claim claim : sheetClaims) {
84	            Person person = byId.get(claim.person());
85	            LocalDate dueBy = LocalDate.parse(claim.dueBy());
86	            boolean earlier = sheetPeriods.stream().anyMatch((p) -> !dueBy.isBefore(LocalDate.parse(p.from()))
87	                    && !dueBy.isAfter(LocalDate.parse(p.to())) && LocalDate.parse(p.to()).isBefore(from));
88	            ClaimStatus then = claim.statusOn(to);
89	            if (person == null || !earlier || (then != ClaimStatus.OPEN && then != ClaimStatus.PENDING)
90	                    || !person.countsOn(claim, to)) {
91	                continue;
92	            }
93	            BigDecimal due = claim.due(sheetRates, person.gradeOn(claim.date()), floor, late);
94	            if (due != null) {
95	                carried.merge(person.id(), due, BigDecimal::add);
96	            }
97	        }
98	        for (Claim claim : sheetClaims) {
99	            LocalDate date = LocalDate.parse(claim.dueBy());
100	            Person person = byId.get(claim.person());
101	            if (person == null || !person.countsOn(claim, to) || date.isBefore(from) || date.isAfter(to)) {
102	                continue;
103	            }
104	            BigDecimal due = claim.due(sheetRates, person.gradeOn(claim.date()), floor, late);
105	            if (due != null) {
106	                total = total.add(due);
107	                perPerson.merge(person.id(), due, BigDecimal::add);
108	            }
109	        }
110	        if (!periods.close(sheet, found.name(), total, perPerson, carried, soft)) {
111	            return false;
112	        }
113	        periods.fixPoolCuts(sheet, found.name(), pools.currentCuts(sheet));
114	        audit.record((soft ? "PERIOD_SOFT_CLOSED" : "PERIOD_CLOSED") + " sheet=" + sheet + " by=" + user + " period=" + found.name() + " total="
115	                + total.toPlainString() + (auto ? " auto=yes" : ""));
116	        return true;
117	    }
118	
119	    /**
120	     * Closes, in order of their to-dates, every open (neither closed nor soft-closed) period of the sheet whose to-date plus the grace days is before
121	     * the sheet's today; none when the sheet has no grace days.
122	     */
123	    public void autoClose(String sheet, String user) {
124	        Integer grace = settings.graceDays(sheet);
125	        if (grace == null) {
126	            return;
127	        }
128	        LocalDate today = clock.today(sheet);
129	        List<Period> due = periods.list(sheet).stream()
130	                .filter((p) -> !p.fixed() && LocalDate.parse(p.to()).plusDays(grace).isBefore(today))
131	                .sorted(Comparator.comparing(Period::to)).toList();
132	        for (Period period : due) {
133	            close(sheet, user, period, true);
134	        }
135	    }
