399	/**
400	 * Checks every pasted opening-balance line (name,period,amount: a person on the sheet by name or alias, a period on
401	 * the sheet, an amount of two decimals, 0.00 or more) before anything is written, so a refused paste sets nothing.
402	 * Blank lines are skipped; a paste with no line is refused.
403	 */
404	public class ValidateOpeningImport {
405	
406	    private static final Pattern AMOUNT = Pattern.compile("\\d+\\.\\d{2}");
407	
408	    public void validate(@PathVariable("sheet") String sheet, @RequestBody OpeningImportRequest request,
409	            People people, Periods periods, Out<ImportedOpenings> imported) throws InvalidPeriodException {
410	        String text = request == null || request.text() == null ? "" : request.text();
411	        List<ImportedOpenings.Line> lines = new ArrayList<>();
412	        int at = 0;
413	        for (String line : text.split("\\r?\\n")) {
414	            at++;
415	            if (line.isBlank()) {
416	                continue;
417	            }
418	            String[] fields = line.split(",", -1);
419	            if (fields.length != 3) {
420	                throw new InvalidPeriodException("Line " + at + ": give name,period,amount");
421	            }
422	            String name = fields[0].trim();
423	            Person person = name.isEmpty() ? null : people.findByName(sheet, name);
424	            if (person == null) {
425	                throw new InvalidPeriodException("Line " + at + ": no one on the sheet is named " + name);
426	            }
427	            String period = fields[1].trim();
428	            if (period.isEmpty() || !periods.named(sheet, period)) {
429	                throw new InvalidPeriodException("Line " + at + ": no period on the sheet is named " + period);
430	            }
431	            String amount = fields[2].trim();
432	            if (!AMOUNT.matcher(amount).matches()) {
433	                throw new InvalidPeriodException("Line " + at + ": the amount must be two decimals, 0.00 or more");
434	            }
435	            lines.add(new ImportedOpenings.Line(person.id(), person.name(), period, new BigDecimal(amount)));
436	        }
437	        if (lines.isEmpty()) {
438	            throw new InvalidPeriodException("Paste at least one line of name,period,amount");
439	        }
440	        imported.set(new ImportedOpenings(lines));
441	    }
442	}
