468	/**
469	 * Adds each person's open figure at the end of the old year's last period to their opening balance for the new year's
470	 * first period: the due now of their claims that count then, whose due-by falls in a period of the old year, and that
471	 * were OPEN or PENDING at that period's end by their status log (a person with none gets no line). Only a first period
472	 * this rollover generated gets openings, so rolling over again does not carry twice. Then audits the
473	 * rollover with how many periods the generator made, keeping it as the sheet's last so it can be undone.
474	 */
475	public class CarryOpenings {
476	    public void carry(@PathVariable("sheet") String sheet, @RequestParam("user") String user,
477	            @Val RolloverYear year, @Val Integer made, Periods periods, Claims claims, People people, Rates rates,
478	            Settings settings, SheetClock clock, Rollovers rollovers, Audit audit) {
479	        List<Rollovers.Opening> set = new ArrayList<>();
480	        List<Period> old = periods.list(sheet).stream()
481	                .filter((p) -> !LocalDate.parse(p.from()).isBefore(year.from())
482	                        && !LocalDate.parse(p.from()).isAfter(year.to()))
483	                .toList();
484	        LocalDate end = old.stream().map((p) -> LocalDate.parse(p.to())).max(Comparator.naturalOrder()).orElseThrow();
485	        Period first = periods.on(sheet, year.next());
486	        if (first != null && !year.before().contains(first.name())) {
487	            List<Rate> sheetRates = rates.list(sheet);
488	            Dated floor = settings.floor(sheet);
489	            Late late = settings.late(sheet, clock.today(sheet));
490	            Map<Long, BigDecimal> open = new LinkedHashMap<>();
491	            List<Claim> sheetClaims = claims.list(sheet);
492	            for (Person person : people.list(sheet)) {
493	                for (Claim claim : sheetClaims) {
494	                    if (claim.person() != person.id()) {
495	                        continue;
496	                    }
497	                    LocalDate dueBy = LocalDate.parse(claim.dueBy());
498	                    boolean inOld = old.stream().anyMatch((p) -> !dueBy.isBefore(LocalDate.parse(p.from()))
499	                            && !dueBy.isAfter(LocalDate.parse(p.to())));
500	                    ClaimStatus then = claim.statusOn(end);
501	                    if (!inOld || (then != ClaimStatus.OPEN && then != ClaimStatus.PENDING)
502	                            || !person.countsOn(claim, end)) {
503	                        continue;
504	                    }
505	                    BigDecimal due = claim.due(sheetRates, person.gradeOn(claim.date()), floor, late);
506	                    if (due != null) {
507	                        open.merge(person.id(), due, BigDecimal::add);
508	                    }
509	                }
510	                BigDecimal amount = open.get(person.id());
511	                if (amount != null && amount.signum() != 0) {
512	                    periods.addOpening(sheet, first.name(), person.id(), amount);
513	                    set.add(new Rollovers.Opening(first.name(), person.id(), amount));
514	                    audit.record("OPENING_SET sheet=" + sheet + " by=" + user + " name=" + person.name() + " period="
515	                            + first.name() + " amount=" + amount.toPlainString());
516	                }
517	            }
518	        }
519	        List<String> generated = periods.list(sheet).stream().map(Period::name)
520	                .filter((name) -> !year.before().contains(name)).toList();
521	        rollovers.keep(sheet, new Rollovers.Rollover(year.fy(), user, clock.today(sheet), generated, set));
522	        audit.record("ROLLOVER sheet=" + sheet + " by=" + user + " fy=" + year.fy() + " periods=" + made);
523	    }
524	}
