380	  return floored + lateCents(claim, floored, late);
381	}
382	
383	
384	/** A person's due-total: the sum of their counted claims' rounded figures (the claims of others are skipped). n/a (undefined) when their grade
385	 *  has no rate on the sheet's today, unless a claim has a figure apart from it (settled, stated, at another grade
386	 *  in force on its date, or from a rate that ended by today on a claim not dated after it): then the figures there are.
387	 *  With a cap (the person's: the sheet's cap less their cut total), a due-total above it is the cap (an n/a one is not capped). */
388	export function personDueCents(
389	  claims: Claim[],
390	  rates: Rate[],
391	  person: Person,
392	  today: string | undefined,
393	  floor: DatedCents,
394	  late: Late,
395	  cap?: bigint,
396	  people: Person[] = [person],
397	): bigint | undefined {
398	  const sum = uncappedPersonDueCents(claims, rates, person, today, floor, late, people);
399	  return sum !== undefined && cap !== undefined && sum > cap ? cap : sum;
400	}
401	
402	/** A person's due-total before the cap: the sum of their figures (see {@link personDueCents}). */
403	export function uncappedPersonDueCents(
404	  claims: Claim[],
405	  rates: Rate[],
406	  person: Person,
407	  today: string | undefined,
408	  floor: DatedCents,
409	  late: Late,
410	  people: Person[] = [person],
411	): bigint | undefined {
412	  const mine = counted(claims.filter((c) => c.person === person.id), [person]);
413	  const parts = heldParts(claims, people, rates, person, floor, late);
414	  // A claim has a figure apart from today's grade when it keeps one, or when another grade in force on its date gives one.
415	  const apart = (c: Claim) => {
416	    const then = gradeOn(person, c.date);
417	    return fixed(c) || (then !== undefined && then !== person.grade && claimFigureCents(c, claimRateOf(rates, then, c), floor) !== undefined)
418	      || (then !== undefined && today !== undefined && c.date <= today && claimFigureCents(c, claimRateOf(rates, then, c), floor) !== undefined);
419	  };
420	  if (rateOf(rates, person.grade, today) === undefined && !mine.some(apart) && parts.length === 0) return undefined;
421	  const own = mine.reduce((sum, c) => {
422	    const due = claimDueCents(c, claimRateOf(rates, gradeOn(person, c.date), c), floor, late);
423	    return sum + (due === undefined ? 0n : ownCents(c, due, people, rates, late));
424	  }, 0n);
425	  return parts.reduce((sum, p) => sum + p.cents, own);
426	}
427	
428	/** A person's settled-total and open-total (in hundredths): the dues of their SETTLED claims that count (at their
429	 *  frozen figures, corrections included) and of their OPEN and PENDING ones that count (see {@link counted}). Together
430	 *  they make the due-total before the cap; a claim with no due adds nothing. Also the score's settled figure: the
431	 *  settled-total less the corrections. */
432	export function splitDueCents(
433	  claims: Claim[],
434	  rates: Rate[],
435	  person: Person,
436	  floor: DatedCents,
437	  late: Late,
438	  people: Person[] = [person],
439	): { settled: bigint; open: bigint; scored: bigint } {
440	  const split = { settled: 0n, open: 0n, scored: 0n };
441	  const add = (c: Claim, due: bigint) => {
442	    if (c.status === 'SETTLED') {
443	      split.settled += due;
444	      if (c.corrects === null) split.scored += due;
445	    } else if (isOpen(c)) split.open += due;
446	  };
447	  for (const c of counted(claims.filter((c) => c.person === person.id), [person])) {
448	    const due = claimDueCents(c, claimRateOf(rates, gradeOn(person, c.date), c), floor, late);
449	    if (due !== undefined) add(c, ownCents(c, due, people, rates, late));
450	  }
451	  for (const { claim, cents } of heldParts(claims, people, rates, person, floor, late)) add(claim, cents);
452	  return split;
453	}
454	
455	/** A person's score: the settled figure of their SETTLED claims that correct nothing (in hundredths) divided by 100, minus 5 for every overdue claim of theirs
456	 *  that counts, rounded half to even to a whole number. */
457	export function scoreOf(settledCents: bigint, overdueCount: number): bigint {
458	  // In ten-thousandths of the score: hundredths divided by 100 is ten-thousandths of a whole.
459	  const scaled = settledCents - 50000n * BigInt(overdueCount);
460	  const abs = scaled < 0n ? -scaled : scaled;
461	  let quotient = abs / 10000n;
462	  const remainder = abs % 10000n;
463	  if (remainder > 5000n || (remainder === 5000n && quotient % 2n === 1n)) quotient += 1n;
464	  return scaled < 0n ? -quotient : quotient;
465	}
466	
467	/** A person's recent settled figure: the sum of their SETTLED claims' frozen figures dated within the 90 days up to
468	 *  and including the sheet's today (today and the 89 days before it); a claim settled with no figure adds nothing. */
469	export function recentSettledCents(claims: Claim[], person: Person, today: string | undefined): bigint {
470	  if (today === undefined) return 0n;
471	  const since = plusDays(today, -89);
472	  return claims
473	    .filter((c) => c.person === person.id && c.status === 'SETTLED' && c.date >= since && c.date <= today)
474	    .reduce((sum, c) => sum + (c.settledDue === null ? 0n : hundredths(c.settledDue)), 0n);
475	}
476	
477	/** Whether a person is active: they have an OPEN or PENDING claim that counts (see {@link counted}) dated within the
478	 *  30 days up to and including the sheet's today (today and the 29 days before it). */
479	export function isActive(claims: Claim[], person: Person, today: string | undefined): boolean {
480	  if (today === undefined) return false;
481	  const since = plusDays(today, -29);
482	  return counted(claims.filter((c) => c.person === person.id), [person]).some(
483	    (c) => isOpen(c) && c.date >= since && c.date <= today,
484	  );
485	}
486	
487	/** Whether a claim is overdue: OPEN or PENDING, not deferred, with its due-by plus its grace before the sheet's today. */
488	export function overdue(claim: Claim, late: Late): boolean {
489	  return isOpen(claim) && !claim.deferred && late.today !== undefined && late.graceBy(claim) < late.today;
490	}
491	
492	/** The overdue claims that count (see {@link counted}) among a person's or the sheet's claims, and the sum of
493	 *  their dues (in hundredths; a claim with no due adds nothing). */
494	export function overdueCents(
495	  claims: Claim[],
496	  people: Person[],
497	  rates: Rate[],
498	  late: Late,
499	  floor: DatedCents,
500	): { count: number; cents: bigint } {
501	  const byId = new Map(people.map((p) => [p.id, p]));
502	  const overdueClaims = counted(claims, people).filter((c) => byId.has(c.person) && overdue(c, late));
503	  const cents = overdueClaims.reduce(
504	    (sum, c) => sum + (claimDueCents(c, claimRateOf(rates, gradeOn(byId.get(c.person)!, c.date), c), floor, late) ?? 0n),
505	    0n,
506	  );
507	  return { count: overdueClaims.length, cents };
508	}
509	
510	/** A person's dues by the age of the claim on the sheet's today (the whole days from its date): their OPEN and
511	 *  PENDING claims that count (see {@link counted}) aged 0 to 30 days, 31 to 60, and 61 or more (in hundredths; a
512	 *  claim dated after today is 0 to 30, and a claim with no due adds nothing). */
513	export function agedCents(
514	  claims: Claim[],
515	  person: Person,
516	  rates: Rate[],
517	  late: Late,
518	  floor: DatedCents,
519	): { upTo30: bigint; upTo60: bigint; over60: bigint } {
520	  const aged = { upTo30: 0n, upTo60: 0n, over60: 0n };
521	  const today = late.today;
522	  for (const c of counted(claims.filter((c) => c.person === person.id), [person])) {
523	    if (!isOpen(c)) continue;
524	    const due = claimDueCents(c, claimRateOf(rates, gradeOn(person, c.date), c), floor, late) ?? 0n;
525	    const days =
526	      today === undefined ? 0 : Math.round((Date.parse(`${today}T00:00:00Z`) - Date.parse(`${c.date}T00:00:00Z`)) / 86_400_000);
527	    if (days <= 30) aged.upTo30 += due;
528	    else if (days <= 60) aged.upTo60 += due;
529	    else aged.over60 += due;
530	  }
531	  return aged;
532	}
533	
534	/** Adds up the people's figures, leaving out the single highest and the single lowest when three or more people
535	 *  have a figure. */
536	export function trimmedSum(figures: bigint[]): bigint {
537	  const sum = figures.reduce((s, f) => s + f, 0n);
538	  if (figures.length < 3) return sum;
539	  const max = figures.reduce((m, f) => (f > m ? f : m));
540	  const min = figures.reduce((m, f) => (f < m ? f : m));
541	  return sum - max - min;
542	}
543	
544	/** The sheet's totals: its claimed-total (everyone's counted claims added up,
545	 *  corrections left out), its due-total (everyone's due-total
546	 *  added up, skipping the people whose due-total is n/a, trimmed — see trimmedSum), and how many of the counted claims
547	 *  are overdue, with their total (each person's overdue-total, trimmed), and its settled-total, open-total and cut
548	 *  total (each person's, trimmed). */
549	export function useSheetTotals(sheet: string): {
550	  claimed: string;
551	  due: bigint;
552	  overdue: { count: number; cents: bigint };
553	  /** Each person's figures before trimming: the due-totals that are not n/a, and everyone's overdue-total,
554	   *  settled-total, open-total and cut total. */
555	  figures: { due: bigint[]; overdue: bigint[]; settled: bigint[]; open: bigint[]; cut: bigint[] };
556	  settled: bigint;
557	  open: bigint;
558	  cut: bigint;
559	  aged: { upTo30: bigint; upTo60: bigint; over60: bigint };
560	} {
561	  const { data: all = [] } = useClaims(sheet);
562	  const { data: people = [] } = usePeople(sheet);
563	  const { data: rates = [] } = useRates(sheet);
564	  const today = useSheetToday(sheet);
565	  const floor = useFloorCents(sheet);
566	  const late = useLate(sheet);
567	  const capOf = useCapCentsOf(sheet);
568	  const { data: pools = [] } = usePools(sheet);
569	  const dues = people
570	    .map((p) => personDueCents(all, rates, p, today, floor, late, capOf(p), people))
571	    .filter((cents): cents is bigint => cents !== undefined);
572	  const due = trimmedSum(dues);
573	  const overdue = overdueCents(all, people, rates, late, floor);
574	  const perPerson = people.map((p) => overdueCents(all, [p], rates, late, floor).cents);
575	  // The settled-total, open-total and cut total: everyone's, trimmed.
576	  const split = people.map((p) => splitDueCents(all, rates, p, floor, late, people));
577	  const settled = split.map((x) => x.settled);
578	  const open = split.map((x) => x.open);
579	  const cut = people.map((p) => personCutCents(pools, p.id));
580	  return {
581	    claimed: claimed(claimedCounted(all, people)),
582	    due,
583	    overdue: { count: overdue.count, cents: trimmedSum(perPerson) },
584	    figures: { due: dues, overdue: perPerson, settled, open, cut },
585	    settled: trimmedSum(settled),
586	    open: trimmedSum(open),
587	    cut: trimmedSum(cut),
588	    // The age buckets: everyone's added up, not trimmed.
589	    aged: people
590	      .map((p) => agedCents(all, p, rates, late, floor))
591	      .reduce(
592	        (s, x) => ({ upTo30: s.upTo30 + x.upTo30, upTo60: s.upTo60 + x.upTo60, over60: s.over60 + x.over60 }),
593	        { upTo30: 0n, upTo60: 0n, over60: 0n },
594	      ),
595	  };
596	}
597	
598	/** Every tag ever carried by a claim on the sheet (`gone`: by claims since gone from it), or carried by a person on it,
599	 *  sorted. */
600	export function sheetTags(claims: Claim[], people: Person[] = [], gone: string[] = []): string[] {
601	  return [
602	    ...new Set([...claims.flatMap((c) => [...c.tagsEver, ...c.tags]), ...people.flatMap((p) => p.tags), ...gone]),
603	  ].sort();
604	}
605	
606	/** The due-total of each tag ever used on the sheet (in hundredths): the dues of the claims that count (see
607	 *  {@link counted}) which carry it or whose person carries it, once each; a claim with two tags counting in both;
608	 *  a claim with no due adds nothing. */
609	export function useTagDueTotals(sheet: string): { tag: string; cents: bigint }[] {
610	  const { data: all = [] } = useClaims(sheet);
611	  const { data: people = [] } = usePeople(sheet);
612	  const { data: rates = [] } = useRates(sheet);
613	  const floor = useFloorCents(sheet);
614	  const late = useLate(sheet);
615	  const { data: shown } = useSheet(sheet);
616	  const byId = new Map(people.map((p) => [p.id, p]));
617	  const totals = new Map(sheetTags(all, people, shown?.tagsGone).map((t) => [t, 0n]));
618	  for (const c of counted(all, people)) {
619	    const person = byId.get(c.person);
620	    if (person === undefined) continue;
621	    const tags = new Set([...c.tags, ...person.tags]);
622	    if (tags.size === 0) continue;
623	    const due = claimDueCents(c, claimRateOf(rates, gradeOn(person, c.date), c), floor, late) ?? 0n;
624	    for (const t of tags) totals.set(t, (totals.get(t) ?? 0n) + due);
625	  }
626	  return [...totals].map(([tag, cents]) => ({ tag, cents }));
627	}
628	
629	/** The due-total of each calendar month (yyyy-mm) any claim on the sheet is dated in, sorted (in hundredths): the dues
630	 *  of the claims that count (see {@link counted}) dated in it; a claim with no due adds nothing. */
631	export function useMonthDueTotals(sheet: string): { month: string; cents: bigint }[] {
632	  const { data: all = [] } = useClaims(sheet);
633	  const { data: people = [] } = usePeople(sheet);
634	  const { data: rates = [] } = useRates(sheet);
635	  const floor = useFloorCents(sheet);
636	  const late = useLate(sheet);
637	  const byId = new Map(people.map((p) => [p.id, p]));
638	  const totals = new Map([...new Set(all.map((c) => c.date.slice(0, 7)))].sort().map((m) => [m, 0n]));
639	  for (const c of counted(all, people)) {
640	    const person = byId.get(c.person);
641	    if (person === undefined) continue;
642	    const due = claimDueCents(c, claimRateOf(rates, gradeOn(person, c.date), c), floor, late) ?? 0n;
643	    const month = c.date.slice(0, 7);
644	    totals.set(month, (totals.get(month) ?? 0n) + due);
645	  }
646	  return [...totals].map(([month, cents]) => ({ month, cents }));
647	}
648	
649	/** Each person's due-total as their row shows it (see {@link personDueCents}): undefined when n/a. */
650	export function usePersonDueCentsOf(sheet: string): (person: Person) => bigint | undefined {
651	  const { data: all = [] } = useClaims(sheet);
652	  const { data: rates = [] } = useRates(sheet);
653	  const today = useSheetToday(sheet);
654	  const floor = useFloorCents(sheet);
655	  const late = useLate(sheet);
656	  const capOf = useCapCentsOf(sheet);
657	  const { data: people = [] } = usePeople(sheet);
658	  return (person) => personDueCents(all, rates, person, today, floor, late, capOf(person), people);
659	}
